window.ROUTE_SUNIAN = {"id":"sunian","name":"苏念","floor":30,"flag1Week":24,"flag2Week":49,"flag1Need":60,"flag2Need":80,"chapters":[{"id":"extra","title":"番外 · 童年","scenes":[{"no":1,"title":"搬来的那天","week":1,"bg":"gate","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"搬家卡车倒进巷子的时候，车尾撞了一下梧桐。叶子落了几片，停在水泥地上，很快被晒卷。"},{"t":"n","text":"你坐在自家门槛上，手里端着一碗凉茶。妈妈让你送的。她说新邻居来了，要打个招呼。"},{"t":"n","text":"车上先下来一个女人，嗓门很大，指挥工人抬衣柜。然后是一个男人，穿公交公司的蓝衬衫，袖口卷到手肘，手背上有一层薄茧。"},{"t":"n","text":"最后下来的是她。她抱着一个纸箱，箱底漏出一截木头的腿。"},{"t":"n","text":"她走到台阶前，纸箱歪了一下。那只木马掉出来，在地上滚了半圈，停在你脚边。"},{"t":"n","text":"木马很旧，漆掉了一半，一条后腿用透明胶缠着，胶已经黄了。"},{"t":"n","text":"她蹲下去捡。你先捡了起来。"},{"t":"c","id":"sunian","text":"谢谢。"},{"t":"n","text":"她说话很轻，尾音有点低。她比你矮半个头，凉鞋里露出晒出印子的脚背。"},{"t":"n","text":"你把木马递给她。她没接稳，木马又掉了。"},{"t":"n","text":"她妈妈在那边喊：「念念，别挡道！」"},{"t":"n","text":"她应了一声，往旁边挪了半步，还是没有走。"},{"t":"c","id":"sunian","text":"我叫苏念。念书的念。"},{"t":"n","text":"你说你叫什么。她跟着念了一遍，念得很慢，像在记。"},{"t":"n","text":"她爸爸从驾驶室拿出一卷绳子，走过来，看了看地上的木马。"},{"t":"npc","name":"苏念爸爸","text":"腿断了。回头我给你粘。"},{"t":"c","id":"sunian","text":"你上次也这么说。"},{"t":"n","text":"她爸爸没接话，弯腰把纸箱抱起来，往楼道里走。"},{"t":"n","text":"他走了两步，又回头，把地上的绳子捡起来，搭在肩上。卡车还停在那里，车厢里剩半车东西。日头很毒，铁皮烫得反光。"},{"t":"n","text":"她妈妈在楼上喊了一声，声音从楼道里传下来，嗡嗡的。"},{"t":"n","text":"她站在原地，把木马抱在怀里，手指按着那条断腿。"},{"t":"n","text":"你手里的凉茶还没送出去。碗壁上凝了一层水珠，顺着你的手腕往下淌。"},{"t":"n","text":"晚饭时，妈妈说，隔壁是老苏家。男人开 12 路，女人在药店。她夹了一筷子菜，又补了一句：「他家闺女比你小两个月。」"},{"t":"n","text":"你端着碗到阳台。对面四楼的灯亮着，窗台上摆着那只木马。"},{"t":"n","text":"她站在窗边，看见你，没有躲。你挥了挥手。她也挥了一下，动作很小。"},{"t":"n","text":"然后两个人各自进屋。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"跑回家拿胶水","hint":"先把它修好再说","eff":{"aff":5.0,"happy":3.0,"familyRel":1.0},"reply":[{"t":"n","text":"你跑回家，翻出爸爸工具箱里的胶水。瓶口堵住了，你用牙咬开，舌尖沾到一点苦味。"},{"t":"n","text":"你们蹲在台阶上。她把木马按住，你往断口上涂胶，涂多了，顺着木头往下流。"},{"t":"n","text":"粘了三次，都滑开。你从口袋里摸出一根橡皮筋，绕了两圈，把那条腿绑住。"},{"t":"n","text":"木马站住了。歪着，但没有倒。"},{"t":"c","id":"sunian","text":"这样它就能站着了。"},{"t":"n","text":"她把木马放在窗台上，退后两步看了看，又把它挪正了一点。"},{"t":"n","text":"她妈妈出来倒水，看见你们蹲在地上，愣了一下，说：「哎哟，这闺女，刚来就交上朋友了。」"}]},{"label":"B","text":"把铁皮青蛙借给她","hint":"让她先有个玩的","eff":{"aff":4.0,"happy":2.0},"reply":[{"t":"n","text":"你跑回家，从抽屉里拿出那只铁皮青蛙。发条有点松，拧两圈才跳。"},{"t":"n","text":"你把它放在她手心。她低头看了很久，拇指在青蛙背上蹭了蹭。"},{"t":"c","id":"sunian","text":"它会跳吗。"},{"t":"n","text":"你说会。她蹲下来，把青蛙放在地上，拧了两圈。"},{"t":"n","text":"青蛙跳了一下，撞到纸箱，翻了个身。"},{"t":"n","text":"她笑出声，很快又捂住嘴，抬头看她妈妈有没有生气。"},{"t":"c","id":"sunian","text":"明天还能借我吗。"},{"t":"n","text":"你说能。她把青蛙还给你，两只手接的，很小心。"}]},{"label":"C","text":"站在门口，等她先说话","hint":"不着急 · 慢慢来","eff":{"aff":2.0,"eq":1.0},"reply":[{"t":"n","text":"你没有动。她也没有动。搬家工从你们中间抬过去一张桌子。"},{"t":"n","text":"过了一会儿，她问：「你几岁。」"},{"t":"n","text":"你说七岁。她说：「我也是。」"},{"t":"n","text":"然后就没有话了。蝉在梧桐上叫，一声接一声。"},{"t":"n","text":"她把木马抱得更紧了一点。你把手里的凉茶递过去，她看了看碗，又看了看你。"},{"t":"c","id":"sunian","text":"你喝吧。我不渴。"},{"t":"n","text":"她说完，舔了一下嘴唇。"}]}]}],"id":"sn_01"},{"no":2,"title":"一把伞","week":5,"bg":"gate","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"九月末，下了一场很大的雨。放学的时候，校门口的积水已经漫到台阶上。"},{"t":"n","text":"你站在传达室屋檐下，书包顶在头上。雨没有要停的意思。"},{"t":"n","text":"苏念从人群里挤过来，撑着一把黑伞。伞很大，伞骨断了一根，那一角塌下去。"},{"t":"c","id":"sunian","text":"走啊。"},{"t":"n","text":"你把书包挪到胸前。她往你这边靠了靠，伞面倾过来。"},{"t":"n","text":"走到半路，你才发现她右边的肩膀全湿了。校服贴在身上，颜色深了一块。"},{"t":"n","text":"你把伞往她那边推。她又推回来。"},{"t":"c","id":"sunian","text":"我近。你家远。"},{"t":"n","text":"其实两家隔着一堵墙。"},{"t":"n","text":"校门口的小卖部亮着灯。林小满从后面追上来，书包在雨里一颠一颠。"},{"t":"npc","name":"林小满","text":"苏念！你又等他！"},{"t":"n","text":"苏念没回头，只说了一句：「顺路。」"},{"t":"n","text":"林小满凑过来，压低声音：「她每天都说顺路。」"},{"t":"n","text":"苏念用伞沿碰了她一下。林小满笑着跑进雨里，踩起一串水。"},{"t":"n","text":"小卖部的玻璃上蒙着雾。柜台里摆着辣条、汽水、五毛钱一包的果丹皮。"},{"t":"n","text":"老板是个胖男人，正用报纸扇风。他看了你们一眼，问：「买什么。」"},{"t":"n","text":"苏念摇头。老板也没再问，把报纸翻了一面。"},{"t":"n","text":"雨敲在铁皮雨棚上，声音很密。她站在你左边，伞柄握得很紧，指节有一点白。你闻到伞面上有一股旧布的味道。"},{"t":"n","text":"苏念停下脚步，摸了摸口袋，摸出两枚硬币。她看了很久，又把手缩回去。"},{"t":"n","text":"你问她买不买。她说：「不买。我妈说辣条脏。」"},{"t":"n","text":"她说完，又看了一眼。"},{"t":"n","text":"到巷口，她妈妈正站在药店门口，手里拿了一条干毛巾。"},{"t":"n","text":"她妈妈把毛巾盖在苏念头上，一边擦一边数落：「你自己都淋湿了，还把伞给别人。」"},{"t":"c","id":"sunian","text":"伞小。"},{"t":"n","text":"她妈妈看了你一眼，叹了口气，从口袋里摸出两块钱，塞给苏念：「去买两串鱼丸。一人一串。」"},{"t":"n","text":"苏念拿着钱，没动。"},{"t":"n","text":"她妈妈说：「去啊。」"},{"t":"n","text":"你站在药店门口，看着她跑。她的凉鞋踩在水里，溅起一串水花。雨小了一点，屋檐还在滴水。"},{"t":"n","text":"她转身往小卖部走，走了两步，回头看你：「你吃不吃辣的。」"},{"t":"n","text":"你说吃。她点点头，跑进雨里。"},{"t":"reff","eff":{"aff":1.0},"note":"苏念好感 +1（无论选项，她都会买两串鱼丸）。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把伞往她那边推","hint":"她湿得比你多","eff":{"aff":5.0,"str":-1.0,"happy":3.0},"reply":[{"t":"n","text":"你伸手抓住伞柄，把伞整个推到她头顶。她愣了一下，抬手要推回来。"},{"t":"n","text":"你往前走了一步，站到伞外。"},{"t":"n","text":"雨点砸在书包上，啪啪地响。她追上来，把伞重新罩住你，力气比刚才大。"},{"t":"c","id":"sunian","text":"你傻不傻。"},{"t":"n","text":"她的声音有点急。你看见她耳朵红了。"},{"t":"n","text":"后面一段路，两个人都在伞里，谁也没再推。伞太小，还是有一边漏雨。"}]},{"label":"B","text":"脱下外套罩在她头上","hint":"先护住她的头发","eff":{"aff":4.0,"happy":2.0,"stress":1.0},"reply":[{"t":"n","text":"你把校服外套脱下来，罩在她头上。她眼前一黑，伸手去扒。"},{"t":"c","id":"sunian","text":"你干嘛。"},{"t":"n","text":"你说跑。你拉着她的书包带，两个人一起往巷子里跑。"},{"t":"n","text":"外套滑下来，盖住她半边脸。她笑得喘不上气，脚下踩进水坑，鞋全湿了。"},{"t":"n","text":"到楼下，她把外套还给你。外套湿透了，沉得像一块布。"},{"t":"c","id":"sunian","text":"明天我帮你洗。"},{"t":"n","text":"你说不用。她说：「我妈说，借了人家的东西要还干净。」"}]},{"label":"C","text":"拉她跑到站台","hint":"雨太大了 · 先躲","eff":{"aff":3.0,"str":1.0,"happy":2.0},"reply":[{"t":"n","text":"你抓住她的手腕，往公交站台跑。她「哎」了一声，伞差点脱手。"},{"t":"n","text":"站台的棚子很窄，挤了七八个人。你们站在最边上，肩膀挨着肩膀。"},{"t":"n","text":"她收了伞，把伞尖朝下，水顺着伞骨流到地上，汇成一小滩。"},{"t":"n","text":"12 路来了。她爸爸在驾驶室，看见你们，抬了抬下巴。"},{"t":"n","text":"她摇头，指了指巷子的方向。车开走了。"},{"t":"c","id":"sunian","text":"我爸要跑完这趟才能下班。"},{"t":"n","text":"她说这话的时候，眼睛看着车尾的红灯。"}]}]}],"id":"sn_02"},{"no":3,"title":"面馆的醋碟","week":8,"bg":"izakaya_night","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"老街的路面是青石板，缝里长着草。苏记面馆在 3 号，门脸不大，招牌是手写的，最后一笔拖得很长。"},{"t":"n","text":"玻璃上贴着价目表：牛肉面八块，素面五块，加蛋一块五。纸边卷起来，用透明胶粘着。"},{"t":"n","text":"外婆坐在门口择菜，腿上盖着一条旧毛巾。她看见你，先笑了：「念念的同学？进来坐。」"},{"t":"n","text":"苏念从后厨出来，袖子挽到手肘，手上沾着面粉。"},{"t":"c","id":"sunian","text":"你怎么来了。"},{"t":"n","text":"你说你妈让你送点东西。你手里其实什么也没拿。"},{"t":"n","text":"她看了你一眼，没有拆穿，往旁边让了让。"},{"t":"n","text":"面馆里只有四张桌子。桌面上铺着塑料布，边角用图钉固定。墙上挂着一台旧风扇，转起来咯吱响。"},{"t":"n","text":"苏念在擦桌子。她擦得很仔细，先横着，再竖着，最后把桌角也抹一遍。"},{"t":"n","text":"你站在旁边看了一会儿。她递给你一块抹布。"},{"t":"c","id":"sunian","text":"别白站着。"},{"t":"n","text":"你擦了两张桌子。她检查了一遍，指着一处水渍：「这儿。」"},{"t":"n","text":"你重新擦。她点点头，把抹布收走。"},{"t":"n","text":"六点半，她爸爸进来了。蓝衬衫，手里拎着一个保温杯，钥匙串往桌上一放，叮当一声。"},{"t":"n","text":"钥匙串上挂着一个公交公司的铁牌，边缘磨得发亮。"},{"t":"npc","name":"苏念爸爸","text":"一碗牛肉面。不要葱。"},{"t":"n","text":"苏念应了一声，往后厨走。走了两步，回头问你：「你吃什么。」"},{"t":"n","text":"你说不用。外婆在门口接话：「来了就吃。外婆请。」"},{"t":"n","text":"她爸爸看了你一眼，把菜单往你那边推了推。"},{"t":"n","text":"你点了一碗素面。苏念在里面喊：「加个蛋！」"},{"t":"n","text":"她爸爸打开保温杯，喝了一口水。杯子里泡着枸杞，浮在上面。"},{"t":"n","text":"面端上来。苏念把两碗面放好，又拿了一个小碟，倒了醋，放在你手边。"},{"t":"n","text":"你没有说过你吃面要放醋。"},{"t":"n","text":"她回到柜台后面，开始包馄饨。皮是早上擀的，馅是荠菜肉的。她一只手托皮，一只手捏，三下就是一个。"},{"t":"n","text":"她爸爸吃面很快，几分钟就见了底。他放下筷子，问：「这次数学考了多少。」"},{"t":"c","id":"sunian","text":"九十八。"},{"t":"n","text":"她爸爸「嗯」了一声，没有再问。"},{"t":"n","text":"外婆在门口说：「念念手稳。以后当老师，板书好看。」"},{"t":"c","id":"sunian","text":"外婆，你都说八百遍了。"},{"t":"n","text":"她嘴上这么说，包馄饨的手没有停。"},{"t":"n","text":"柜台上的电话响了。她妈妈打来的，说药店盘点到十点，不回来吃饭。"},{"t":"n","text":"苏念说知道了。挂了电话，她把留给妈妈的那碗面往旁边挪了挪，盖上一个大碗。"},{"t":"n","text":"你走到巷口，回头看了一眼。苏记的招牌还亮着，玻璃上蒙着一层白汽。"},{"t":"n","text":"苏念在擦最后一张桌子。她爸爸坐在门口的小板凳上，低头看手机。"},{"t":"n","text":"外婆把择好的菜装进篮子，慢慢站起来。苏念放下抹布，过去扶她。"},{"t":"n","text":"你站在暗处看了一会儿，才回家。"},{"t":"n","text":"那天的面有点咸。醋碟里的醋，你蘸完了。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"帮她收碗","hint":"手上勤快一点","eff":{"aff":4.0,"familyRel":2.0,"happy":2.0},"reply":[{"t":"n","text":"你把空碗摞起来，端到后厨。水池很低，你弯腰的时候，水溅了一身。"},{"t":"n","text":"苏念跟进来，看了一眼，说：「碗要冲两遍。」"},{"t":"n","text":"她站在你旁边，教你怎么转碗。她的手碰到你的手背，很快缩回去。"},{"t":"n","text":"外婆在外面喊：「念念，别让客人干活！」"},{"t":"c","id":"sunian","text":"他不是客人。"},{"t":"n","text":"她说完，自己也愣了一下，低头继续冲碗。"}]},{"label":"B","text":"陪她写作业","hint":"在柜台边坐一会儿","eff":{"aff":3.0,"eq":2.0,"happy":2.0},"reply":[{"t":"n","text":"你把作业本摊在靠窗的桌上。她坐在对面，膝盖上放着一本数学练习册。"},{"t":"n","text":"面馆的灯是暖黄的，照得纸页有点旧。她写题的时候，左手会按住纸角。"},{"t":"n","text":"你有一道应用题不会。她探头看了一眼，说：「你先画线段。」"},{"t":"n","text":"她讲了一遍，你没听懂。她又讲一遍，换了一种说法。"},{"t":"c","id":"sunian","text":"这回懂了吗。"},{"t":"n","text":"你说懂了。她看着你，不太信，又出了一道差不多的。"},{"t":"n","text":"你做对了。她把笔帽扣上，说：「还行。」"}]},{"label":"C","text":"先回家","hint":"家里还等着吃饭","eff":{"aff":1.0,"familyRel":1.0,"happy":1.0},"reply":[{"t":"n","text":"你说你妈还等着。外婆给你装了两个卤蛋，用纸袋包着，塞进你手里。"},{"t":"n","text":"苏念送你到门口。巷子里的路灯刚亮，飞虫绕着灯罩转。"},{"t":"c","id":"sunian","text":"明天早上，六点四十。"},{"t":"n","text":"你问她等什么。"},{"t":"c","id":"sunian","text":"一起走啊。反正顺路。"},{"t":"n","text":"她说完就回去了。门帘落下来，里面的灯光被切成一条一条。"}]}]}],"id":"sn_03"},{"no":4,"title":"十二岁的站台","week":12,"bg":"station","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"小学毕业的那个暑假，苏念约你去坐她爸爸的首班车。"},{"t":"n","text":"早上五点五十，天刚亮。巷子里只有扫地的声音，竹扫帚一下一下，刮着水泥地。"},{"t":"n","text":"她站在站台边，手里拎着一个塑料袋，里面两瓶豆浆，瓶口扎着。"},{"t":"c","id":"sunian","text":"你得坐到终点站。中间别下车。"},{"t":"n","text":"你问她为什么。"},{"t":"c","id":"sunian","text":"终点站才有意思。"},{"t":"n","text":"12 路来了。车头灯亮着，车里没有开灯。她爸爸坐在驾驶室，看见你们，把门打开。"},{"t":"n","text":"车开得很慢。每一站都停，没有人上下。她数着站名，声音很小。"},{"t":"n","text":"「解放路。文化宫。老菜场。纺织厂。」"},{"t":"n","text":"你问她数这个干什么。"},{"t":"c","id":"sunian","text":"我爸说，开这条线十九年，闭着眼睛都知道哪儿有个坑。"},{"t":"n","text":"终点站在城北。站牌锈了，上面「纺织厂」三个字掉了一个角。厂子早就停了，铁门锁着，里面长着草。"},{"t":"n","text":"她爸爸把车停好，从驾驶室下来，活动了一下腰。"},{"t":"npc","name":"苏念爸爸","text":"二十分钟。别走远。"},{"t":"n","text":"他走进旁边的调度室，门没有关严。"},{"t":"n","text":"站台后面是一条河。河面很平，漂着几片树叶。远处有人在钓鱼，坐着一动不动。"},{"t":"n","text":"苏念把豆浆递给你。瓶子还是温的。"},{"t":"c","id":"sunian","text":"我妈煮的。放了糖。"},{"t":"n","text":"你喝了一口。糖放多了，有点腻。她看着你的表情，笑了。"},{"t":"c","id":"sunian","text":"我就说少放点。"},{"t":"n","text":"你们坐在站台的长椅上。椅子是铁的，漆掉了，露出下面的锈。"},{"t":"n","text":"过了一会儿，她问：「你初中去哪儿。」"},{"t":"n","text":"你说三中。她说她也是。"},{"t":"c","id":"sunian","text":"我查过了。三中初一六个班，我在三班。"},{"t":"n","text":"她说完，补了一句：「你几班我不知道。分班榜还没贴。」"},{"t":"n","text":"风吹过来，带着河水的味道。她把豆浆瓶抱在手里，手指在瓶身上敲。"},{"t":"n","text":"你忽然问她：「你家会不会搬走。」"},{"t":"n","text":"她愣了一下。"},{"t":"c","id":"sunian","text":"搬哪儿去。"},{"t":"n","text":"你说不知道。城里，或者更远的地方。"},{"t":"n","text":"她低头想了一会儿，指了指身后的公交车。"},{"t":"c","id":"sunian","text":"我家搬不走。我爸的车就这一条线。从纺织厂到火车站，十九年。"},{"t":"n","text":"她说得很慢，像是在给你讲一道题。"},{"t":"c","id":"sunian","text":"你要是走丢了，就坐 12 路回来。终点站下车，我在这儿。"},{"t":"n","text":"你笑了一声。她没有笑。"},{"t":"c","id":"sunian","text":"我说真的。"},{"t":"n","text":"调度室的门开了。她爸爸走出来，手里拿着一个搪瓷杯。"},{"t":"npc","name":"苏念爸爸","text":"走了。"},{"t":"n","text":"回程的车开得快一些。太阳升起来，照在车窗上，有一层灰。"},{"t":"n","text":"苏念靠着椅背睡着了。她的头一点一点，最后靠在你的肩膀上。"},{"t":"n","text":"你不敢动。车过了一个坑，颠了一下，她皱皱眉，没有醒。"},{"t":"n","text":"到站的时候，她爸爸从后视镜里看了一眼，没有按喇叭，等了一会儿才开口。"},{"t":"npc","name":"苏念爸爸","text":"到了。"},{"t":"n","text":"苏念睁开眼，坐直，理了理头发。她好像不知道自己刚才靠着你。"},{"t":"n","text":"下车的时候，她爸爸叫住你。"},{"t":"npc","name":"苏念爸爸","text":"以后她要是等你，你早点来。"},{"t":"n","text":"他说完，把车开走了。"},{"t":"n","text":"站台上剩下你们两个。苏念低头看着鞋尖，耳朵有一点红。"},{"t":"c","id":"sunian","text":"我爸话多。你别听他的。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把站名记下来","hint":"这一条线 · 记牢","eff":{"aff":5.0,"eq":1.0,"happy":3.0},"reply":[{"t":"n","text":"你从书包里翻出一支笔，在作业本背面写下站名：解放路、文化宫、老菜场、纺织厂。"},{"t":"n","text":"写到「纺织厂」的时候，笔没水了。你用力描了几遍，只留下一个浅浅的印子。"},{"t":"n","text":"苏念把她的笔递给你。笔杆上有牙印。"},{"t":"n","text":"你重新写了一遍。她在旁边看着，说：「你字真丑。」"},{"t":"n","text":"你把本子合上，放进口袋。"},{"t":"c","id":"sunian","text":"记这个干嘛。"},{"t":"n","text":"你说，怕以后忘了。"}]},{"label":"B","text":"把木马还给她","hint":"它该回家了","eff":{"aff":4.0,"happy":3.0},"reply":[{"t":"n","text":"你从书包里拿出那只小木马。上次她忘在你家窗台上，你收了起来。"},{"t":"n","text":"断腿已经用胶粘好，外面缠了一圈白线。线是你妈妈缝扣子用的。"},{"t":"n","text":"她接过去，翻来覆去地看。"},{"t":"c","id":"sunian","text":"你粘的？"},{"t":"n","text":"你说你妈粘的，你按着。"},{"t":"n","text":"她笑了一下，把木马放进随身的小布包。"},{"t":"c","id":"sunian","text":"那它以后就住包里。再断一次，我还找你。"}]},{"label":"C","text":"说「我不走」","hint":"先给她一句准话","eff":{"aff":3.0,"happy":2.0,"stress":1.0},"reply":[{"t":"n","text":"你说，你不走。"},{"t":"n","text":"她看着你，看了很久。"},{"t":"c","id":"sunian","text":"你说了不算。你妈说了才算。"},{"t":"n","text":"你说你妈听你的。"},{"t":"n","text":"她被这句话逗笑了，笑完又收敛起来。"},{"t":"c","id":"sunian","text":"行。那我记着了。"},{"t":"n","text":"她伸出手，小拇指弯着。你愣了一下，也伸出手。"},{"t":"n","text":"两个人的小拇指勾在一起。她的手很凉，指尖有面粉的味道。"}]}]}],"id":"sn_04"}]},{"id":"ch1","title":"第一章 · 高中","scenes":[{"no":5,"title":"同路","week":1,"bg":"gate","cast":["sunian","luchen"],"steps":[{"t":"cast","list":["sunian","luchen"],"focus":"sunian"},{"t":"n","text":"高一开学那天，分班榜贴在校门口的红墙上。四张红纸，用图钉按着，边角被风掀起。"},{"t":"n","text":"人很多。你从人缝里挤进去，找自己的名字。"},{"t":"n","text":"七班，第三排。你往旁边看，三班的名单上，苏念在第二个。"},{"t":"n","text":"她也在看榜。她先找到自己的名字，然后目光往下移，一行一行地找。"},{"t":"n","text":"找到你的时候，她停了一下，嘴唇动了动，没有出声。"},{"t":"n","text":"你走过去。她把手从榜上收回来。"},{"t":"c","id":"sunian","text":"七班。我在三班。"},{"t":"n","text":"你说你看见了。"},{"t":"c","id":"sunian","text":"教室在四楼。你们班在二楼。"},{"t":"n","text":"她说完，从书包侧袋里拿出一瓶豆浆，递给你。"},{"t":"c","id":"sunian","text":"我妈早上煮多了。"},{"t":"n","text":"瓶身还是温的。你接过来，她转身往教学楼走。"},{"t":"n","text":"从那天起，每天早上六点四十，她都在巷口等。"},{"t":"n","text":"她从不迟到。你迟到了三次，每一次她都站在那棵梧桐下面，书包背得很正。"},{"t":"n","text":"第一次你跑过去，她说：「明天早五分钟。」"},{"t":"n","text":"第二次你跑过去，她说：「你鞋带开了。」"},{"t":"n","text":"第三次，她没有说话，把豆浆塞给你，自己先走了。走了十几步，又放慢。"},{"t":"n","text":"她走路很快。你常常要小跑两步才能跟上。"},{"t":"n","text":"林小满有时候会骑车追上来。她车筐里塞着书包，车铃按得叮叮响。"},{"t":"npc","name":"林小满","text":"苏念！你又走这么早！"},{"t":"n","text":"苏念头也不回：「你骑你的。」"},{"t":"n","text":"林小满绕到你们前面，倒着骑，冲你挤眼睛。"},{"t":"npc","name":"林小满","text":"你知道吗，她每天定两个闹钟。一个六点，一个六点零五。"},{"t":"c","id":"sunian","text":"林小满。"},{"t":"n","text":"林小满笑着骑远了。车铃在巷子里响了一路。"},{"t":"n","text":"校门口有广播站。每天早读前，会念一段天气和校内通知。"},{"t":"n","text":"开学第三周，广播里的声音换了。你听了一句就站住了。"},{"t":"n","text":"是苏念。她念得很慢，把「今天最高气温二十九度」念得像一句别的话。"},{"t":"n","text":"她念完，停了两秒，补了一句：「请同学们记得带水。」"},{"t":"n","text":"你站在楼梯口，听完才上楼。"},{"t":"n","text":"课间你问她。她正在收语文作业，头也没抬。"},{"t":"c","id":"sunian","text":"广播站缺人。林小满替我报的。"},{"t":"n","text":"你问她为什么念天气。"},{"t":"c","id":"sunian","text":"总得有人说。"},{"t":"c","id":"sunian","text":"你听出来了？"},{"t":"n","text":"你说听出来了。她「哦」了一声，耳朵有一点红。"},{"t":"n","text":"同班的第一周，陆沉坐在你前排。他很少回头，桌面上永远只有一本书和一支笔。"},{"t":"n","text":"有一次你的笔掉了，滚到他脚边。他弯腰捡起来，放在你桌上，没有看你。"},{"t":"n","text":"你想说谢谢。他已经转回去了。"},{"t":"n","text":"第一次月考后，放学时间推迟了。七班加了晚自习，三班没有。"},{"t":"n","text":"你在站台找到她。她坐在长椅上，膝盖上摊着一本单词书，书页被风吹得翻来翻去。"},{"t":"c","id":"sunian","text":"你们班以后都这么晚？"},{"t":"n","text":"你说可能。"},{"t":"n","text":"她把单词书合上，站起来，拍了拍裙子。"},{"t":"c","id":"sunian","text":"那我等你十分钟。过时不候。"},{"t":"n","text":"你问她真不等。"},{"t":"n","text":"她看着你，很认真。"},{"t":"c","id":"sunian","text":"你试试。"},{"t":"n","text":"第二天你跑着出校门，用了八分钟。她坐在长椅上，看见你，把单词书收起来。"},{"t":"c","id":"sunian","text":"还行。"},{"t":"n","text":"她书包侧袋里，还插着一瓶豆浆。瓶盖上的点，已经快被磨掉了。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"每天等她一起走","hint":"把六点四十留出来","eff":{"aff":4.0,"happy":3.0,"stress":-1.0},"reply":[{"t":"n","text":"你把闹钟调到六点二十。头两天还是差点迟到，第三天开始，你比她先到。"},{"t":"n","text":"她从楼道里出来，看见你站在梧桐下，脚步慢了半拍。"},{"t":"c","id":"sunian","text":"今天怎么这么早。"},{"t":"n","text":"你说怕她等。"},{"t":"n","text":"她没有说话，把豆浆递给你。瓶盖上用记号笔画了一个小点。"},{"t":"n","text":"你问她那是什么。"},{"t":"c","id":"sunian","text":"糖。今天放了糖。"},{"t":"n","text":"以后每天早上，瓶盖上都有那个点。"}]},{"label":"B","text":"骑车先走","hint":"省下二十分钟","eff":{"aff":1.0,"int":2.0,"stress":1.0},"reply":[{"t":"n","text":"你骑了家里的旧自行车。链条有点松，蹬起来咔哒响。"},{"t":"n","text":"第一天你从她身边过去，按了一下铃。她抬头，往旁边让了让。"},{"t":"n","text":"你说先走了。她点头，说：「路上看车。」"},{"t":"n","text":"你骑出十几米，从后视镜里看了一眼。她还站在原地，低头整理书包带。"},{"t":"n","text":"到学校，你比平时早了十五分钟。你坐在教室里，把英语单词背了两遍。"},{"t":"n","text":"第二天早上，巷口没有人。"},{"t":"n","text":"你骑到校门口，看见她从公交车上下来。她也看见你了，挥了挥手。"},{"t":"n","text":"那天放学，她在站台等你。她说：「以后我坐我爸的车。早上不用等了。」"}]},{"label":"C","text":"偶尔等","hint":"看当天的情况","eff":{"aff":2.0,"stress":-2.0,"happy":1.0},"reply":[{"t":"n","text":"你没有答应每天。她也没有再问。"},{"t":"n","text":"有时候你早，就在巷口站一会儿。有时候你晚，她已经走了。"},{"t":"n","text":"有一天你追到校门口，她正站在广播站门口看稿子。"},{"t":"c","id":"sunian","text":"你跑什么。"},{"t":"n","text":"你说怕你走了。"},{"t":"c","id":"sunian","text":"我走了就学校见。又不是不见。"},{"t":"n","text":"她说得轻描淡写。但那天放学，她在站台等了你二十分钟。"}]}]}],"id":"sn_05"},{"no":6,"title":"家长会","week":6,"bg":"corridor","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"家长会那天，走廊里摆满了塑料凳。每个班门口贴着一张成绩单，用红笔标了名次。"},{"t":"n","text":"你妈妈来得很早。她穿了一件平时不舍得穿的外套，手里拎着一袋橘子，说要给老师。"},{"t":"n","text":"班主任在教室里讲话。你站在后门外，隔着玻璃看。"},{"t":"n","text":"你妈妈坐在第二排，背挺得很直。她听得很认真，偶尔点头。"},{"t":"n","text":"成绩单传出来的时候，你看见她的手指在纸上停了一下。"},{"t":"n","text":"班主任说：「有些同学，初中底子不错，上了高中就松了。家长要多盯一盯。」"},{"t":"n","text":"你没有听见名字。但你妈妈回头看了一眼后门。"},{"t":"n","text":"你往旁边躲了半步。"},{"t":"n","text":"走廊另一头，苏念抱着一摞签到表，正在一张一张地收。"},{"t":"n","text":"她今天穿的是校服，袖口洗得有点发白。她走到三班门口，停下来，看了看里面。"},{"t":"n","text":"三班的家长席上，有两个空位。"},{"t":"n","text":"她站了一会儿，低头在签到表上写了几个字。"},{"t":"n","text":"你走过去，看见她写的是：「家长未到。苏念。」"},{"t":"n","text":"她把笔帽扣上，抬头看见你，没有躲。"},{"t":"c","id":"sunian","text":"我爸跑晚班。我妈店里盘点。"},{"t":"n","text":"你说你可以帮她跟老师说一声。"},{"t":"c","id":"sunian","text":"不用。我自己签。"},{"t":"n","text":"她把签到表抱好，往办公室走。走了两步，又回来。"},{"t":"c","id":"sunian","text":"你妈在里面？"},{"t":"n","text":"你点头。"},{"t":"n","text":"她看了一眼教室，又看了一眼你。"},{"t":"n","text":"教室门开了。你妈妈走出来，脸色不太好。她看见苏念，愣了一下。"},{"t":"npc","name":"你妈妈","text":"这是……"},{"t":"n","text":"你说同学。"},{"t":"n","text":"苏念叫了一声「阿姨好」。她声音很稳。"},{"t":"n","text":"班主任跟在后面出来，手里拿着成绩单。"},{"t":"npc","name":"班主任","text":"苏念，你来得正好。你这次年级三十二，保持住，省师大没问题。"},{"t":"n","text":"苏念「嗯」了一声。"},{"t":"n","text":"班主任又看向你妈妈：「他这次数学退步了十二分。回去要说说。」"},{"t":"n","text":"你妈妈的脸沉下来。你低下头。"},{"t":"n","text":"苏念忽然开口。"},{"t":"c","id":"sunian","text":"老师，他这次数学一百一十八。上次一百零六。"},{"t":"n","text":"班主任愣了一下，翻了翻手里的表。"},{"t":"c","id":"sunian","text":"年级排名也进了两名。只是英语掉了。"},{"t":"n","text":"走廊里安静了几秒。班主任咳了一声，说：「那……还行。英语要补。」"},{"t":"n","text":"苏念说完，抱着签到表走了。她走得很快，校服背后的粉笔灰一颠一颠。"},{"t":"n","text":"你妈妈看着她的背影，问：「这姑娘谁家的？」"},{"t":"n","text":"你说，隔壁老苏家。"},{"t":"n","text":"你妈妈「哦」了一声，把橘子往你手里一塞：「给老师送去。」"},{"t":"n","text":"你回到校门口。你妈妈站在路灯下，手里那袋橘子少了一半。"},{"t":"n","text":"她说：「走了。」"},{"t":"n","text":"你跟着她往车站走。走出十几米，你回头看了一眼。"},{"t":"n","text":"苏念站在教学楼门口，抱着签到表。她冲你抬了抬下巴，意思是「快走」。"},{"t":"n","text":"你转过头。路灯把你的影子拉得很长，一直拖到她脚下。"},{"t":"reff","eff":{"aff":1.0},"note":"苏念好感 +1（无论选项，她都会替你说那句话）。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"追出去，跟她走一段","hint":"先跟她说声谢谢","eff":{"aff":5.0,"happy":4.0,"stress":-3.0},"reply":[{"t":"n","text":"你把橘子塞回妈妈手里，说你一会儿回来。"},{"t":"n","text":"你追到楼梯口。她正站在窗边，把签到表按在墙上，一张一张理齐。"},{"t":"n","text":"你叫她的名字。她回头。"},{"t":"n","text":"你说谢谢。"},{"t":"c","id":"sunian","text":"谢什么。"},{"t":"n","text":"你说，数学那个。"},{"t":"n","text":"她把表理好，抱在怀里。"},{"t":"c","id":"sunian","text":"你本来就一百一十八。我又没瞎说。"},{"t":"n","text":"她往楼下走。你跟在她旁边。"},{"t":"n","text":"走到操场边，她忽然停下来。"},{"t":"c","id":"sunian","text":"你妈会骂你吗。"},{"t":"n","text":"你说可能会。"},{"t":"c","id":"sunian","text":"那你今天别惹她。她穿那么新的外套，是给你撑面子的。"}]},{"label":"B","text":"回教室，继续听","hint":"先把家长会开完","eff":{"aff":2.0,"familyRel":2.0,"stress":2.0},"reply":[{"t":"n","text":"你回到后门。你妈妈已经坐回去了，背没有刚才直。"},{"t":"n","text":"班主任还在讲。你听见「高考」「一本率」「不能松」几个词，反反复复。"},{"t":"n","text":"散会的时候，你妈妈把成绩单折好，放进包里。"},{"t":"npc","name":"你妈妈","text":"回家再说。"},{"t":"n","text":"她走在前面。你跟在后面，看见她外套的后领有一道折痕，大概是压了很久。"},{"t":"n","text":"走到校门口，她忽然停下。"},{"t":"npc","name":"你妈妈","text":"刚才那个姑娘，说得对。你数学是进步了。"},{"t":"n","text":"她说完，又往前走。"}]},{"label":"C","text":"去操场，一个人待一会儿","hint":"先让自己静下来","eff":{"aff":1.0,"stress":-4.0,"happy":1.0},"reply":[{"t":"n","text":"你从后门溜出去，绕到操场。"},{"t":"n","text":"操场没有灯。跑道边的草里有虫叫。你坐在看台上，看见教学楼的窗户一格一格亮着。"},{"t":"n","text":"过了很久，有人走过来。脚步很轻。"},{"t":"n","text":"苏念在你旁边坐下，隔着两个座位。"},{"t":"n","text":"她没有问你怎么了。她把一颗糖放在你们中间的座位上。"},{"t":"n","text":"糖是橘子味的，糖纸有点皱。"},{"t":"n","text":"你剥开吃了。她坐了一会儿，站起来。"},{"t":"c","id":"sunian","text":"你妈在门口等你。我跟她说了，你在厕所。"}]}]}],"id":"sn_06"},{"no":7,"title":"便当","week":11,"bg":"classroom","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"那天中午你没去食堂。教室里只剩两个人，一个在睡觉，一个在写题。"},{"t":"n","text":"你趴在桌上，脸埋在胳膊里。肚子叫了一声，你没有动。"},{"t":"n","text":"后门有人敲了两下。很轻，像怕吵醒谁。"},{"t":"n","text":"你抬头。苏念站在门口，手里拎着一个保温袋，袋子上印着超市的促销字样。"},{"t":"c","id":"sunian","text":"出来。"},{"t":"n","text":"你跟她走到天台。天台上晒着几条拖把，风一吹，拖把布条碰到栏杆。"},{"t":"n","text":"她把保温袋放在水泥台上，拉开拉链，拿出一个饭盒。"},{"t":"n","text":"饭盒是旧的，盖子上有一道裂。她打开，热气冒出来。"},{"t":"n","text":"番茄炒蛋，煎带鱼，米饭压得很实，上面撒了一点芝麻。"},{"t":"c","id":"sunian","text":"我妈多做的。"},{"t":"n","text":"她把筷子递给你，自己在旁边坐下，从书包里拿出一本错题本。"},{"t":"n","text":"你问她吃了没有。"},{"t":"c","id":"sunian","text":"吃了。"},{"t":"n","text":"她说完，翻了一页错题本。你看见她的耳朵有一点红。"},{"t":"n","text":"番茄炒蛋是甜的。带鱼煎得有点焦，边上一圈脆。"},{"t":"n","text":"你吃了两口，她才抬头。"},{"t":"c","id":"sunian","text":"咸不咸。"},{"t":"n","text":"你说正好。"},{"t":"n","text":"她「嗯」了一声，继续看错题本。风把她的头发吹到脸边，她抬手别到耳后。"},{"t":"n","text":"你吃到一半，林小满从楼梯口探出头。"},{"t":"npc","name":"林小满","text":"我就说在这儿！苏念，你自己还没吃呢。"},{"t":"n","text":"苏念合上错题本：「我吃了。」"},{"t":"npc","name":"林小满","text":"你吃什么了。你早上就啃了个馒头。"},{"t":"n","text":"苏念看了她一眼。林小满捂住嘴，退后半步。"},{"t":"n","text":"你放下筷子。"},{"t":"n","text":"林小满小声说：「她妈这周出差。她去外婆家住的。这饭是她自己早上做的，六点就起来了。」"},{"t":"n","text":"苏念把错题本卷起来，敲了一下林小满的头。"},{"t":"c","id":"sunian","text":"你话真多。"},{"t":"n","text":"林小满跑了。天台上剩下你们两个，还有那盒吃到一半的饭。"},{"t":"n","text":"你看着她。她低头把错题本的边角抚平。"},{"t":"c","id":"sunian","text":"看什么。凉了就不好吃了。"},{"t":"n","text":"你重新拿起筷子。她坐在旁边，没有再翻本子。"},{"t":"n","text":"你把带鱼夹了一块，放到饭盒盖上，推到她那边。"},{"t":"n","text":"她看了两秒，拿起来吃了。"},{"t":"n","text":"吃得很慢。"},{"t":"n","text":"你这才注意到，她的手背靠近虎口的地方，有一道浅红色的印子。"},{"t":"n","text":"像是油溅的。"},{"t":"n","text":"第二天中午，你提前五分钟到天台。她已经在了，饭盒放在水泥台上，盖子擦得很干净。"},{"t":"n","text":"她看见你，把饭盒往你那边推了推。"},{"t":"c","id":"sunian","text":"今天不是我妈做的。"},{"t":"n","text":"你打开。是蛋炒饭，里面放了火腿丁和玉米。"},{"t":"c","id":"sunian","text":"我炒的。可能有点咸。"},{"t":"n","text":"你吃了一口。确实咸。"},{"t":"n","text":"你说好吃。她看着你，眼睛弯了一下，很快又收住。"},{"t":"n","text":"她坐在旁边，从书包里拿出两个橘子，剥了一个，分你一半。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把剩下的都吃完","hint":"这是她一早做的","eff":{"aff":6.0,"happy":5.0,"stress":-6.0},"reply":[{"t":"n","text":"你把饭盒里的饭扒得很干净，连番茄汁都用米饭擦了一遍。"},{"t":"n","text":"她看着，嘴角动了一下。"},{"t":"c","id":"sunian","text":"你几天没吃饭了。"},{"t":"n","text":"你说食堂的菜不好吃。"},{"t":"n","text":"她把饭盒收过去，盖上盖子。动作很轻。"},{"t":"c","id":"sunian","text":"明天别吃面包了。"},{"t":"n","text":"你问她明天还有吗。"},{"t":"n","text":"她站起来，把保温袋拎在手里。"},{"t":"c","id":"sunian","text":"看情况。"},{"t":"n","text":"她走到楼梯口，回头补了一句：「你把汤也喝了。在袋子里。」"}]},{"label":"B","text":"分她一半","hint":"她也没吃","eff":{"aff":5.0,"happy":4.0,"stress":-4.0},"reply":[{"t":"n","text":"你把饭盒推到中间，把筷子掉个头，递给她。"},{"t":"n","text":"她愣了一下。"},{"t":"c","id":"sunian","text":"我吃过了。"},{"t":"n","text":"你说，那看着我吃。"},{"t":"n","text":"她看了你一会儿，接过筷子，夹了一小块蛋。"},{"t":"n","text":"吃完，她把筷子还给你，说：「剩下的你吃。我真的吃了。」"},{"t":"n","text":"她说不像假的。她坐在旁边，晒着太阳，眼睛眯起来。"},{"t":"n","text":"你们一人一口，把一盒饭吃完。最后剩一块带鱼，谁也没动。"},{"t":"c","id":"sunian","text":"你吃。"},{"t":"n","text":"你夹给她。她夹回来。最后两个人一起笑了。"}]},{"label":"C","text":"逞强说吃过了","hint":"不想让她再跑一趟","eff":{"aff":-3.0,"stress":3.0,"happy":-2.0},"reply":[{"t":"n","text":"你说你吃过了。在食堂吃的。"},{"t":"n","text":"她看着你，又看了看饭盒。"},{"t":"c","id":"sunian","text":"哦。"},{"t":"n","text":"她把饭盒盖上，放回保温袋。动作还是那么轻。"},{"t":"n","text":"你站在旁边，手插在口袋里。天台上很安静，只有拖把布条在响。"},{"t":"c","id":"sunian","text":"那我带回去。晚上热一热还能吃。"},{"t":"n","text":"她拎着袋子下楼。走了几步，停下来，没有回头。"},{"t":"c","id":"sunian","text":"下次不想吃，就直说。别浪费。"},{"t":"n","text":"你张了张嘴。楼梯门在她身后合上。"},{"t":"n","text":"那天下午，你饿得胃疼。放学的时候，你的桌肚里多了一个面包，还有一张纸条：「明天中午，天台。」"}]}]}],"id":"sn_07"},{"no":8,"title":"她的志愿表","week":21,"bg":"corridor","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"高三的走廊比平时安静。倒计时牌挂在教导处门口，数字一天换一次。"},{"t":"n","text":"志愿草表发下来那天，班主任把苏念叫进了办公室。"},{"t":"n","text":"你抱着一摞作业本经过，门没有关严。"},{"t":"npc","name":"班主任","text":"你这个排名，省师大稳的。为什么不冲一冲？"},{"t":"n","text":"苏念的声音很轻，你听不清她说了什么。"},{"t":"npc","name":"班主任","text":"本城师范是提前批，定向。签了就要回去。你想清楚。"},{"t":"n","text":"你往前走，走到走廊尽头，把作业本放下。"},{"t":"n","text":"过了十分钟，苏念出来了。她手里拿着一张表，对折了两次。"},{"t":"n","text":"她看见你，没有意外。"},{"t":"c","id":"sunian","text":"你都听见了。"},{"t":"n","text":"你说听见一点。"},{"t":"n","text":"她把表递给你。提前批，本城师范，小学教育，定向。"},{"t":"n","text":"下面有一行小字：毕业后须在本市基础教育岗位服务六年。"},{"t":"n","text":"你问她为什么。"},{"t":"n","text":"她往天台走。你跟上去。"},{"t":"n","text":"天台上晾着几条床单，被风吹得鼓起来。她走到栏杆边，把表放在台子上，用一块石头压住。"},{"t":"c","id":"sunian","text":"我爸腰不好。上个月去医院，医生说不能再久坐。"},{"t":"n","text":"她说得很平。"},{"t":"c","id":"sunian","text":"他开了半辈子公交。除了这个，不会别的。我妈那个药店，一个月两千八。"},{"t":"n","text":"她顿了一下。"},{"t":"c","id":"sunian","text":"本城师范有定向补贴。学费免一半，毕业有编制。"},{"t":"n","text":"你问她是不是因为这个。"},{"t":"c","id":"sunian","text":"一半。"},{"t":"n","text":"她把石头挪开，把表拿起来。"},{"t":"c","id":"sunian","text":"另一半是因为陈老师。"},{"t":"n","text":"陈老师是她小学班主任，退休了，住在老街。她每周去看一次，帮着买菜、读报纸。"},{"t":"c","id":"sunian","text":"她教了三十八年。退休那天，学校送了她一个保温杯。她跟我说，教书这个事，要说值，也值。要说不值，也真不值。"},{"t":"n","text":"她笑了一下。"},{"t":"c","id":"sunian","text":"我就想试试。"},{"t":"n","text":"你没有说话。风把床单吹得啪啪响。"},{"t":"n","text":"她低下头，把表重新对折。"},{"t":"n","text":"折到一半，一张纸从她的英语书里滑出来。"},{"t":"n","text":"你捡起来。是省师大的招生简章，彩印的，边角已经软了。"},{"t":"n","text":"简章上有一行被她用铅笔画过的字：小学教育（师范），全省招生 120 人。"},{"t":"n","text":"她伸手来拿。你没有立刻给她。"},{"t":"n","text":"天快黑了。她把志愿表放进书包，压在最里面。"},{"t":"n","text":"那张省师大的简章，她没有扔。她把它夹回英语书，第三十八页。"},{"t":"n","text":"你看见了，没有说。"},{"t":"n","text":"她背好书包，往楼梯口走。走了两步，回头。"},{"t":"c","id":"sunian","text":"先留着。留着又不犯法。"},{"t":"n","text":"她说完就下楼了。脚步声一级一级，很稳。"},{"t":"n","text":"你在天台上又站了一会儿。楼下的路灯一盏一盏亮起来。"},{"t":"n","text":"你想起她说的「一半」。另外一半是什么，她没有说完。"},{"t":"n","text":"你也没有再问。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"问她「你真的想好了吗」","hint":"把话问到底","eff":{"aff":5.0,"eq":2.0,"happy":2.0},"reply":[{"t":"n","text":"你把简章递过去，问她：「你真的想好了吗。」"},{"t":"n","text":"她接过去，没有马上回答。"},{"t":"n","text":"她把简章和志愿表放在一起，看了很久。"},{"t":"c","id":"sunian","text":"想好了。也没想好。"},{"t":"n","text":"她说，她算过。省师大四年，学费加生活费，大概六万。本城师范定向，能省一半。她爸爸的腰，等不了六年。"},{"t":"c","id":"sunian","text":"但我也想过，如果我去了省城，会不会不一样。"},{"t":"n","text":"她抬起头。"},{"t":"c","id":"sunian","text":"想这些没用。人不能什么都占着。"},{"t":"n","text":"你说，你可以帮她。"},{"t":"n","text":"她看了你一眼，摇头。"},{"t":"c","id":"sunian","text":"你帮得了我一时。帮不了我一辈子。"},{"t":"n","text":"她说得很轻，但没有商量的余地。"}]},{"label":"B","text":"说「你值得更好的」","hint":"把不甘心说出来","eff":{"aff":2.0,"stress":3.0,"happy":-1.0},"reply":[{"t":"n","text":"你说，你值得更好的。"},{"t":"n","text":"她愣了一下，然后笑了。笑得不太像平时。"},{"t":"c","id":"sunian","text":"什么叫更好的。"},{"t":"n","text":"你说省师大，更大的城市，更多的可能。"},{"t":"n","text":"她把简章拿回去，抚平折角。"},{"t":"c","id":"sunian","text":"你觉得本城师范不好？"},{"t":"n","text":"你说不是。"},{"t":"c","id":"sunian","text":"那你是在替我不甘心。"},{"t":"n","text":"你语塞。"},{"t":"n","text":"她把两张纸叠在一起，夹回书里。"},{"t":"c","id":"sunian","text":"我不需要别人替我不甘心。我自己有。"},{"t":"n","text":"她说完，语气软了一点。"},{"t":"c","id":"sunian","text":"我知道你是好意。但这是我的事。"}]},{"label":"C","text":"什么都不问，陪她站一会儿","hint":"有些话不必问","eff":{"aff":4.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"你把简章还给她。她接过去，夹回英语书里。"},{"t":"n","text":"你们两个站在栏杆边，看楼下的操场。有人在跑步，一圈一圈。"},{"t":"n","text":"过了很久，她开口。"},{"t":"c","id":"sunian","text":"你怎么不问。"},{"t":"n","text":"你说，你想说的时候会说。"},{"t":"n","text":"她侧过头看了你一眼。"},{"t":"c","id":"sunian","text":"你有时候挺聪明的。"},{"t":"n","text":"她把手伸进校服口袋，摸出两颗糖，给你一颗。"},{"t":"n","text":"糖是薄荷味的。你含着，舌头有点凉。"}]}]}],"id":"sn_08"},{"no":9,"title":"车票（Flag1）","week":24,"bg":"gate","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"毕业典礼在礼堂开了两个小时。空调坏了一半，前排的人拿节目单扇风。"},{"t":"n","text":"校长讲话，优秀毕业生讲话，家长代表讲话。你坐在七班中间，校服领口有点紧。"},{"t":"n","text":"散场的时候，礼堂里乱成一团。有人在哭，有人在拍照，有人把校服外套扔到了树上。"},{"t":"n","text":"那件外套挂在梧桐的枝丫上，白色的，像一面旗。"},{"t":"n","text":"你在校门口等了十分钟。"},{"t":"n","text":"卖花的小贩推着车经过，桶里的向日葵有点蔫。"},{"t":"n","text":"三班的人出来得晚。林小满走在最前面，眼睛红的，手里攥着一包纸巾。"},{"t":"n","text":"她看见你，吸了吸鼻子。"},{"t":"npc","name":"林小满","text":"苏念在后面。她给班主任写东西。"},{"t":"n","text":"又过了几分钟，苏念从里面出来。"},{"t":"n","text":"她手里抱着一摞同学录，最上面那本的边角卷了。她的头发还是半扎着，那根奶白色的发绳换了一根新的。"},{"t":"n","text":"她走到你旁边，站定。两个人都没说话。"},{"t":"n","text":"公交车来了一辆，又走了。站台上的人陆续散了。"},{"t":"n","text":"她把同学录往上托了托。"},{"t":"c","id":"sunian","text":"你怎么还在这。"},{"t":"c","id":"sunian","text":"你等多久了。"},{"t":"n","text":"你说十分钟。"},{"t":"n","text":"她低头看了一眼你的鞋。"},{"t":"c","id":"sunian","text":"骗人。你鞋上全是灰。"},{"t":"n","text":"你没有反驳。她也没有再问。"},{"t":"n","text":"风把她的头发吹起来。她伸手按住，动作和很多年前一样。"},{"t":"n","text":"她从那摞同学录里抽出一本，翻开。是你的那本。"},{"t":"n","text":"你接过来。她的字很小，写得很端正。"},{"t":"n","text":"只写了四个字：按时吃饭。"},{"t":"n","text":"旁边画了一辆公交车，歪歪扭扭的，车轮一大一小。"},{"t":"c","id":"sunian","text":"画得不好。你别笑。"},{"t":"n","text":"你翻到最后一页，想写点什么。笔拿在手里，半天没落下去。"},{"t":"n","text":"她看着你，没有催。"},{"t":"n","text":"最后你写了「你也是」。三个字，写得比平时用力。"},{"t":"n","text":"她接过去看了看，合上。"},{"t":"c","id":"sunian","text":"就这样吧。"},{"t":"n","text":"她把同学录抱好，又从口袋里摸出一样东西，塞进你手心。"},{"t":"n","text":"是一张公交车票。从你家门口，到三中。日期是四年前的九月一日，边角已经软了。"},{"t":"n","text":"票面上印着 12 路，票价一元。字被磨得有点淡。"},{"t":"n","text":"你抬头看她。"},{"t":"c","id":"sunian","text":"我那时候想，如果你去的地方很远，我就每个月去看你一次。"},{"t":"n","text":"她顿了一下。"},{"t":"c","id":"sunian","text":"后来发现，车票挺贵的。"},{"t":"n","text":"她笑了一下，眼睛有点红。"},{"t":"n","text":"你捏着那张票。纸很薄，被手心的汗浸得有点软。"},{"t":"c","id":"sunian","text":"毕业那天，你回来一趟。"},{"t":"n","text":"她说的是四年以后，她大学毕业那天。你听懂了。"},{"t":"n","text":"她把同学录换了个姿势抱着，看着你。"},{"t":"c","id":"sunian","text":"不用现在回答我。"},{"t":"n","text":"她说完就往前走。走了两步，又停下来，没有回头。"},{"t":"n","text":"她走进巷子口的时候，路灯刚好亮起来。她的影子被拉得很长，和你的影子并在一起，又分开。"},{"t":"n","text":"12 路来了。车头灯照过来，站牌上的字白了一下。"},{"t":"n","text":"你没有上。"},{"t":"n","text":"车门开了，又关上。车开走的时候，你看见驾驶室里的司机不是她爸爸。"},{"t":"n","text":"你把车票拿出来，对着路灯看。"},{"t":"n","text":"四年前的九月一日。那天你们第一次一起走路上学。她迟到了两分钟，跑得满脸通红。"},{"t":"n","text":"你把票放回去，按了按。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把车票收好，说「我会回来」","hint":"这一次给她一句准话","eff":{"aff":8.0,"happy":4.0,"stress":-2.0,"flag1":true},"reply":[{"t":"n","text":"你把车票放进钱包最里层，压在那张学生证后面。"},{"t":"n","text":"你说，你会回来。"},{"t":"n","text":"她的背僵了一下。过了两秒，她才转过身。"},{"t":"c","id":"sunian","text":"你说话算数。"},{"t":"n","text":"你说算数。"},{"t":"n","text":"她看着你，眼睛里的水光没有掉下来。"},{"t":"c","id":"sunian","text":"那我把话放这儿。你要是不回来，我就当没说过。"},{"t":"n","text":"她说完，又补了一句，声音很轻。"},{"t":"c","id":"sunian","text":"但我会记着。"},{"t":"n","text":"她转身走了。这一次没有停。"}]},{"label":"B","text":"说「太远了，别等」","hint":"先把话说清楚","eff":{"aff":-3.0,"stress":3.0,"happy":-2.0,"flag1":true},"reply":[{"t":"n","text":"你说，太远了。别等。"},{"t":"n","text":"她没有回头。站台上很安静，远处有人在放毕业歌。"},{"t":"c","id":"sunian","text":"我没等。"},{"t":"n","text":"她的声音很平。"},{"t":"c","id":"sunian","text":"我就是告诉你一声。你回不回来，是你的事。"},{"t":"n","text":"她往前走。走了几步，抬手抹了一下脸。"},{"t":"n","text":"你站在原地。手里那张票，边角硌着你的掌心。"},{"t":"n","text":"你想追上去。脚却没有动。"}]},{"label":"C","text":"开玩笑说「车票能报销吗」","hint":"把话岔开 · 气氛还在","eff":{"aff":2.0,"eq":2.0,"happy":1.0,"flag1":true},"reply":[{"t":"n","text":"你说，这票能报销吗。"},{"t":"n","text":"她愣了一下，然后笑出声。笑得肩膀抖了两下。"},{"t":"c","id":"sunian","text":"你想得美。"},{"t":"n","text":"她抬手擦了一下眼角，动作很快，像在赶一只虫。"},{"t":"c","id":"sunian","text":"一块钱。你自己留着。"},{"t":"n","text":"她把同学录往上抱了抱。"},{"t":"c","id":"sunian","text":"我走了。我妈等着我回去吃饭。"},{"t":"n","text":"她走了两步，停下来。"},{"t":"c","id":"sunian","text":"你也是。按时吃饭。"}]}]}],"low":{"steps":[{"t":"n","text":"你在校门口等到路灯亮。"},{"t":"n","text":"她出来的时候，和几个女生一起。她看见你，挥了挥手。"},{"t":"n","text":"她走过来，手里也抱着一本同学录，但没有递给你。"},{"t":"c","id":"sunian","text":"毕业快乐。"},{"t":"n","text":"她说完，就被几个女生拉走了。有人在喊去吃散伙饭。"},{"t":"n","text":"你站在原地。手里那本同学录，一直没递出去。"},{"t":"n","text":"她走了十几米，回头看了一眼。你举了举手。"},{"t":"n","text":"她也举了举手，很快放下。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"叫住她","hint":"至少把同学录给她","eff":{"aff":3.0,"happy":-1.0,"stress":1.0},"reply":[{"t":"n","text":"你喊了一声她的名字。她停下来，跟同伴说了句什么，走回来。"},{"t":"n","text":"你把同学录递过去。她接过来，翻了两页。"},{"t":"c","id":"sunian","text":"你字还是这么丑。"},{"t":"n","text":"她笑了一下，从口袋里摸出一支笔，在最后一页写了自己的名字和电话。"},{"t":"c","id":"sunian","text":"以后……有空联系。"},{"t":"n","text":"她说完就走了。这一次没有回头。"}]},{"label":"B","text":"站在原地","hint":"把话咽回去","eff":{"stress":2.0,"happy":-2.0},"reply":[{"t":"n","text":"你没有喊。她走远了，混进人群里，看不见了。"},{"t":"n","text":"你把同学录塞进书包。封面上有一块灰，你擦了两下，没有擦掉。"},{"t":"n","text":"12 路来了。你上了车，坐在最后一排。"},{"t":"n","text":"车经过她家楼下的时候，你看见四楼的灯亮着。窗台上没有木马。"}]}]}],"affMax":60},"id":"sn_09","grantFlagOnMain":"flag1"}]},{"id":"ch2","title":"第二章 · 大学","scenes":[{"no":10,"title":"录取通知书","week":25,"bg":"gate","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"通知书是下午到的。邮递员的摩托车在巷口熄了火，喊了一声你的名字。"},{"t":"n","text":"信封比想象中薄。你捏着它上楼，听见自己的脚步声。"},{"t":"n","text":"楼道里的声控灯坏了一盏，走到三楼要跺一下脚。"},{"t":"n","text":"那所学校的名字印在左上角，烫金，摸上去有一点凸。你把信封翻过来，又翻回去。"},{"t":"n","text":"妈妈在厨房关了火。爸爸把老花镜推上去，两个人凑在一起看，看了很久。妈妈说：「我就知道。」然后转身去切西瓜，刀有一点抖。"},{"t":"n","text":"傍晚，苏念在门口敲了两下。她手里也拿着一封信。"},{"t":"n","text":"她的信封是红色的，比你的厚。封口已经拆开，边上有一道撕歪的口子。"},{"t":"c","id":"sunian","text":"本城师范。小学教育。"},{"t":"n","text":"她没问你的学校在哪里。她把信折好，放进口袋。"},{"t":"c","id":"sunian","text":"我妈包了饺子，叫你过来吃。"},{"t":"n","text":"楼道里的声控灯灭了。她跺了一下脚，灯又亮起来，照见她鞋尖上的一点灰。"},{"t":"n","text":"她家桌上摆着三盘饺子，还有一盘切好的酱牛肉。她妈妈在厨房里喊：「来了没有？」"},{"t":"c","id":"sunian","text":"来了！"},{"t":"n","text":"她爸爸坐在桌边，手里拿着她的录取通知书，翻来覆去地看。看了第三遍，才放下。"},{"t":"npc","name":"苏念爸爸","text":"定向。毕业有编制。"},{"t":"n","text":"他说这话的时候，声音比平时低。"},{"t":"npc","name":"苏念妈妈","text":"你爸今天跟调度室的人说了三回。人家都烦他了。"},{"t":"n","text":"她爸爸咳了一声，拿起筷子：「吃饺子。」"},{"t":"n","text":"苏念给你夹了一个。饺子是白菜猪肉的，皮有点厚。"},{"t":"n","text":"她妈妈问你：「你那个学校，在哪儿啊？」"},{"t":"n","text":"苏念的筷子停了一下。"},{"t":"n","text":"吃过饭，她送你到巷口。路灯下飞虫很多，绕着灯泡转。"},{"t":"c","id":"sunian","text":"你什么时候走。"},{"t":"n","text":"你说还没定。"},{"t":"n","text":"她点点头，把被风吹到脸边的头发别到耳后。"},{"t":"c","id":"sunian","text":"走之前，来面馆吃碗面。我外婆念叨你。"},{"t":"n","text":"你说好。"},{"t":"n","text":"她妈妈在楼上喊她。她应了一声，往回跑。跑了两步，回头冲你挥了挥手。"},{"t":"n","text":"她家门上的红信封还贴在那儿，边角被风掀起，啪嗒啪嗒地响。"},{"t":"reff","eff":{"aff":2.0},"note":"`city` 写入；苏念好感 +2（无论选项，她都会来叫你吃饺子）。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"去更远的地方","hint":"去更远的地方 · 眼界 ↑","eff":{"int":3.0,"happy":2.0,"stress":4.0,"aff":-2.0},"reply":[{"t":"n","text":"你说了学校的名字。她「哦」了一声，低头把醋碟往你那边推了推。"},{"t":"c","id":"sunian","text":"那挺好的。大城市。"},{"t":"n","text":"她笑了一下。眼睛没有弯。"},{"t":"n","text":"饺子是白菜猪肉的。你吃了两碗，她吃了半碗。"},{"t":"n","text":"她妈妈问：「那得坐火车吧？几个钟头？」"},{"t":"n","text":"苏念替你说了一个数。她说完，自己愣了一下。"},{"t":"c","id":"sunian","text":"我查过。"},{"t":"n","text":"她低下头，把碗里最后一个饺子夹破，蘸了很多醋。"}]},{"label":"B","text":"留在本城","hint":"留在本城 · 离家近一点","eff":{"aff":6.0,"familyRel":4.0,"happy":3.0},"reply":[{"t":"n","text":"你说，你打算留在本城。"},{"t":"n","text":"她抬头看你，筷子停在半空。"},{"t":"c","id":"sunian","text":"真的？"},{"t":"n","text":"她问完就低下头，耳朵有一点红。"},{"t":"c","id":"sunian","text":"我不是那个意思。本城……本城也挺好的。"},{"t":"n","text":"她给你夹了一个饺子，自己忘了吃。"},{"t":"n","text":"她妈妈在厨房里说：「那敢情好。以后常来，阿姨给你包饺子。」"},{"t":"n","text":"她爸爸「嗯」了一声，给你倒了半杯汽水。"}]},{"label":"C","text":"先把日子过起来","hint":"先挣一点钱 · 早一点长大","eff":{"fin":5.0,"eq":2.0,"stress":3.0,"happy":-1.0},"reply":[{"t":"n","text":"你说，还没想好。先把表叔店里的活干完。"},{"t":"c","id":"sunian","text":"也行。想好了告诉我。"},{"t":"n","text":"她起身去端饺子汤。围裙带子松了，你提醒她，她「嗯」了一声。"},{"t":"n","text":"她妈妈在厨房里叹气：「你说这孩子，分数也不低……」"},{"t":"n","text":"苏念把汤放在你面前，打断她：「妈，汤要凉了。」"}]}]}],"id":"sn_10"},{"no":11,"title":"她在你的城市","week":31,"bg":"campus","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"她来你的城市，参加省里的师范生教学技能大赛。"},{"t":"n","text":"比赛在师范大学的综合楼。你在楼下等她，手里拿了两瓶水。"},{"t":"n","text":"她出来的时候，穿着白衬衫和黑色长裤，头发扎得很低。手里拎着一个保温袋，另一只手抱着一块小白板。"},{"t":"c","id":"sunian","text":"你怎么来了。"},{"t":"n","text":"你说你请了半天假。"},{"t":"c","id":"sunian","text":"不用请假。我明天就走。"},{"t":"n","text":"她嘴上这么说，脚步却慢下来，跟你并排走。"},{"t":"n","text":"综合楼后面有一间空教室。她借了钥匙，说要再练一遍。"},{"t":"n","text":"教室很小，黑板是绿的，擦得不太干净。她把小白板放在讲台上，试了试高度。"},{"t":"c","id":"sunian","text":"你坐第三排。假装是学生。"},{"t":"n","text":"你坐下。她把头发重新扎了一遍，深吸一口气。"},{"t":"c","id":"sunian","text":"上课。同学们好。"},{"t":"n","text":"她的声音比平时高一点，尾音有点抖。"},{"t":"n","text":"她讲的是《秋天的雨》。讲到「秋天的雨，有一盒五彩缤纷的颜料」，她转身在黑板上写字。"},{"t":"n","text":"粉笔断了一次。她愣了一下，弯腰捡起来，继续写。"},{"t":"n","text":"写完，她回头，看见你，忽然忘了下一句。"},{"t":"n","text":"教室里安静了几秒。她的耳朵红了。"},{"t":"c","id":"sunian","text":"……你笑什么。"},{"t":"n","text":"你说你没笑。"},{"t":"c","id":"sunian","text":"你嘴角在动。"},{"t":"n","text":"她低下头，笑了一下，很快收住。"},{"t":"c","id":"sunian","text":"重来。这次你不许看我。"},{"t":"n","text":"你转过头，看窗外的梧桐。她的声音在身后响起来，一句一句，慢慢稳了。"},{"t":"n","text":"练到第三遍，她停下来。"},{"t":"c","id":"sunian","text":"可以了。"},{"t":"n","text":"她收拾东西，把小白板擦干净。粉笔灰落在她的黑裤子上，一拍就是一道白印。"},{"t":"n","text":"她的指导老师周老师在门口等她。五十多岁，短发，说话很直。"},{"t":"npc","name":"周老师","text":"讲完了？比昨天好。就是语速还是快，小学生跟不上。"},{"t":"n","text":"苏念点头，把这句话记在本子上。"},{"t":"npc","name":"周老师","text":"下午比赛，别想着拿奖。把那四十分钟上完。"},{"t":"n","text":"她走了。苏念松了口气，靠在讲台边。"},{"t":"c","id":"sunian","text":"周老师带了我三年。她一说我，我就不会走路了。"},{"t":"n","text":"你问她紧不紧张。"},{"t":"c","id":"sunian","text":"紧张。早饭都没吃。"},{"t":"n","text":"她把保温袋拎起来，放在课桌上，拉开拉链。"},{"t":"n","text":"里面是两个饭团，用保鲜膜包着，捏得不太圆。"},{"t":"c","id":"sunian","text":"路上吃。我早上做的。本来想在车上吃，忘了。"},{"t":"n","text":"你拿了一个。米是温的，里面包着肉松和一点咸菜。"},{"t":"n","text":"她看你吃，自己也拿了一个，咬了一口。"},{"t":"c","id":"sunian","text":"有点散。水放多了。"},{"t":"n","text":"你说挺好吃。她看了你一眼，没说话，把剩下的一半吃完了。"},{"t":"n","text":"她赶晚上七点的高铁回学校。你送她到车站。"},{"t":"n","text":"候车厅里人很多。她把保温袋塞给你。"},{"t":"c","id":"sunian","text":"路上吃。别在车上睡着了，会坐过站。"},{"t":"n","text":"你问她什么时候再来。"},{"t":"c","id":"sunian","text":"不知道。下学期要实习。"},{"t":"n","text":"广播开始检票。她拎起包，走了两步，回头。"},{"t":"c","id":"sunian","text":"你回去吧。外面冷。"},{"t":"n","text":"你没有动。她也没有再劝，转身进了检票口。"},{"t":"n","text":"保温袋里还剩一个饭团。你坐在回程的公交车上，把它吃了。"},{"t":"n","text":"饭团已经凉了，米有点硬。你还是吃完了。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"当她的模拟学生，陪她练完","hint":"把四十分钟上完","eff":{"aff":6.0,"happy":4.0,"stress":-2.0},"reply":[{"t":"n","text":"你举手，假装是学生：「老师，五彩缤纷是什么意思。」"},{"t":"n","text":"她愣了一下，然后笑了。"},{"t":"c","id":"sunian","text":"这位同学问得好。"},{"t":"n","text":"她蹲下来，在你的课桌边，用很慢的话解释了一遍。她看着你的眼睛，像真的在看一个八岁的孩子。"},{"t":"n","text":"讲完，她问：「懂了吗。」"},{"t":"n","text":"你说懂了。她站起来，拍了拍手上的粉笔灰。"},{"t":"c","id":"sunian","text":"你比我们班孩子好教。"},{"t":"n","text":"下午的比赛，她拿了二等奖。奖状是粉色的，她卷起来，塞进书包侧袋。"}]},{"label":"B","text":"带她去吃本城的东西","hint":"比赛前先吃顿热的","eff":{"aff":4.0,"happy":3.0,"fin":-2.0},"reply":[{"t":"n","text":"你说，先吃饭。她看了看表，说还有一个半小时。"},{"t":"n","text":"你带她去了学校后门的小店。她点了一碗馄饨，吃得很急，烫了舌头。"},{"t":"c","id":"sunian","text":"跟我们家那边不一样。皮薄。"},{"t":"n","text":"她吃了半碗，放下勺子。"},{"t":"c","id":"sunian","text":"不行，吃多了上台会打嗝。"},{"t":"n","text":"你把剩下的吃了。她看着你，说：「你最近是不是没好好吃饭。」"},{"t":"n","text":"你说有。她说：「你下巴都尖了。」"},{"t":"n","text":"她说完，从包里拿出一板奶片，放在桌上。"},{"t":"c","id":"sunian","text":"拿着。饿了吃一片。"}]},{"label":"C","text":"只在赛后见一面","hint":"不打扰她比赛","eff":{"aff":1.0,"stress":-1.0,"happy":1.0},"reply":[{"t":"n","text":"你说你在楼下等。她点点头，说：「也行。上面乱。」"},{"t":"n","text":"你在楼下的花坛边坐了三个小时。中间去便利店买了一瓶水，又回来。"},{"t":"n","text":"她出来的时候，天已经擦黑。奖状卷在手里，脸上的妆掉了一半。"},{"t":"c","id":"sunian","text":"你一直在这儿？"},{"t":"n","text":"你说没有，刚来。"},{"t":"n","text":"她看了一眼你脚边的两个空水瓶，没有拆穿。"},{"t":"c","id":"sunian","text":"二等奖。"},{"t":"n","text":"她说得很轻，像怕这个词太重。"}]}]}],"id":"sn_11"},{"no":12,"title":"周三晚上十点","week":33,"bg":"bedroom_night","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"手机里有十二条未读。你一条一条往下翻。"},{"t":"n","text":"苏念的消息很短："},{"t":"c","id":"sunian","text":"今天食堂的番茄炒蛋是甜的。"},{"t":"c","id":"sunian","text":"我妈问你怎么不来了。"},{"t":"c","id":"sunian","text":"你那边下雨了吗。"},{"t":"n","text":"最后一条是晚上八点：「今天不打了。外婆摔了一跤，我在医院。」"},{"t":"n","text":"你打了一行字，又删掉。再打一行，又删掉。"},{"t":"n","text":"十点，宿舍熄灯。你躺在床上，把手机举在脸上面。"},{"t":"n","text":"十点二十，电话来了。"},{"t":"n","text":"那头很吵。有人在喊「让一让」，还有推车的轮子声。"},{"t":"c","id":"sunian","text":"喂。"},{"t":"n","text":"你问她外婆怎么样。"},{"t":"c","id":"sunian","text":"股骨头。要手术。我妈在办手续。"},{"t":"n","text":"她说得很平，像在念一张单子。"},{"t":"c","id":"sunian","text":"我今天没去上课。跟老师请了假。"},{"t":"n","text":"你问她吃饭没有。"},{"t":"n","text":"那头安静了两秒。"},{"t":"c","id":"sunian","text":"忘了。"},{"t":"n","text":"你听见她笑了一下，很轻。"},{"t":"c","id":"sunian","text":"你别来。来了我还要照顾你。"},{"t":"n","text":"你说你可以帮忙。"},{"t":"c","id":"sunian","text":"你帮什么。你连医院的门朝哪边开都不知道。"},{"t":"n","text":"她说完，语气软了一点。"},{"t":"c","id":"sunian","text":"我不是那个意思。我是说，你来了，也进不去病房。现在只让一个人陪。"},{"t":"n","text":"走廊里有广播在叫号。她把手机拿远了一点，过了一会儿才回来。"},{"t":"c","id":"sunian","text":"我得挂了。医生来了。"},{"t":"n","text":"你说好。"},{"t":"n","text":"挂断之前，她忽然说：「你那边下雨了吗。」"},{"t":"n","text":"你说下了。"},{"t":"c","id":"sunian","text":"那你把窗关好。"},{"t":"n","text":"熄灯以后，宿舍里有人在打呼。你盯着天花板，把手机屏幕按亮，又按灭。"},{"t":"n","text":"窗外有火车经过，很长的一声。"},{"t":"n","text":"你想起她说的「你别来」。你说不清那是客气，还是真的。"},{"t":"n","text":"手机亮了一下。她发来一张照片：医院走廊的长椅，上面放着一件叠好的外套。"},{"t":"c","id":"sunian","text":"外婆睡了。我也睡了。晚安。"},{"t":"n","text":"你回了「晚安」。她没有再回。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"固定每周一个晚上打电话","hint":"把这件事放进日程","eff":{"aff":5.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"你们约在周三晚上十点。第一次打了四十分钟，第二次二十分钟，第三次只有八分钟。"},{"t":"n","text":"但每个周三，她都会在十点前把手机充好电。"},{"t":"n","text":"有一次她在改教案，电话那头一直有笔尖划纸的声音。"},{"t":"n","text":"你说你先忙。她说不用，把手机夹在肩膀和耳朵之间。"},{"t":"c","id":"sunian","text":"你说话。我听着。"},{"t":"n","text":"你就说了一些没用的事：食堂的菜，室友的呼噜，楼下新开的奶茶店。"},{"t":"n","text":"她「嗯」了几声。笔尖的声音慢慢停了。"},{"t":"n","text":"过了一会儿，你听见她呼吸变长。"},{"t":"c","id":"sunian","text":"我睡了一会儿。"},{"t":"n","text":"你说你听出来了。"},{"t":"c","id":"sunian","text":"你刚才说的那个奶茶店，甜不甜。"}]},{"label":"B","text":"忙起来，想起来再回","hint":"先顾眼前 · 关系会淡","eff":{"stress":1.0,"happy":-2.0,"aff":-5.0},"reply":[{"t":"n","text":"你后来回了一条「最近有点忙」。她回：「好，你忙。」"},{"t":"n","text":"再后来，她的消息从每天一条，变成三天一条，再变成一周一条。"},{"t":"n","text":"你偶尔在夜里想起她，点开对话框，看见最后一条是她发的：「外婆出院了。」"},{"t":"n","text":"你回了一个「好」。她没有再回。"},{"t":"n","text":"有一天你翻到她的朋友圈。一张照片，医院走廊的窗户，窗外是早上五点的天。"},{"t":"n","text":"配的字是：「今天也是好天气。」"},{"t":"n","text":"你点了一个赞。过了很久，又取消了。"}]},{"label":"C","text":"周末坐车回去","hint":"突然出现 · 她会记住","eff":{"fin":-4.0,"aff":8.0,"happy":4.0,"stress":3.0},"reply":[{"t":"n","text":"你买了周五最晚的一班车，站了三个小时。到她学校时，宿舍已经锁门了。"},{"t":"n","text":"她从楼上跑下来，穿着拖鞋，头发乱着。"},{"t":"c","id":"sunian","text":"你怎么不提前说。"},{"t":"n","text":"她说完，眼圈就红了。"},{"t":"n","text":"你把手里的袋子递过去。里面是两盒牛奶，一袋橘子，还有一包她爱吃的奶片。"},{"t":"n","text":"她接过去，低头看了很久。"},{"t":"c","id":"sunian","text":"你坐了几个小时。"},{"t":"n","text":"你说三个。"},{"t":"n","text":"她抬手擦了一下眼睛，动作很快。"},{"t":"c","id":"sunian","text":"傻子。明天一早我还要去医院。"},{"t":"n","text":"第二天，你陪她去了医院。她在病房里给外婆削苹果，削得很慢，皮没有断。"},{"t":"n","text":"外婆躺在床上，看着你们，笑了。"},{"t":"npc","name":"外婆","text":"念念，这就是那个……"},{"t":"c","id":"sunian","text":"外婆。"},{"t":"n","text":"外婆不说了，只是笑。"}]}]}],"id":"sn_12"},{"no":13,"title":"暑假回家（Flag1 回响 / 补发）","week":37,"bg":"home","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"车晚点两个小时。到家时，天已经黑了。"},{"t":"n","text":"妈妈在厨房，油烟机很响。爸爸坐在沙发上看电视，声音开得很大，其实在打瞌睡。"},{"t":"n","text":"饭桌上，他们问起毕业后的打算。考研，考公，还是回来。"},{"t":"n","text":"你说，还没想好。"},{"t":"n","text":"爸爸「嗯」了一声，把鱼肚子上的肉夹到你碗里。"},{"t":"n","text":"妈妈问：「苏念那丫头，现在怎么样了？」"},{"t":"n","text":"你说她挺好。在小学见习。"},{"t":"n","text":"妈妈点点头，说：「那丫头稳当。」"},{"t":"n","text":"吃过饭，苏念在巷口等你。她手里两瓶汽水，一瓶已经不冰了。"},{"t":"n","text":"她晒黑了，胳膊上有一道手表印。头发剪短了一点，还是半扎着。"},{"t":"c","id":"sunian","text":"走走吧。"},{"t":"n","text":"你们沿着河堤走。河面上有船，灯一串一串地挂着。"},{"t":"n","text":"她说起见习的事。她带四年级，班上有四十二个孩子。"},{"t":"c","id":"sunian","text":"有个男孩叫小宇。爸妈在外地，跟奶奶过。开学第一天，他坐在最后一排，不说话。"},{"t":"c","id":"sunian","text":"我让他当语文课代表。他现在每天收作业，收得可认真了。"},{"t":"n","text":"你问她外婆怎么样。"},{"t":"c","id":"sunian","text":"出院了。腿脚不利索，面馆盘出去了。"},{"t":"n","text":"她说得很轻。"},{"t":"c","id":"sunian","text":"招牌还留着。我外婆说，等小宇他们长大了，说不定还有人记得苏记的牛肉面。"},{"t":"n","text":"河堤尽头有一家便利店。她进去买了两根冰棍，一根绿豆，一根红豆。"},{"t":"n","text":"她把绿豆的给你。"},{"t":"c","id":"sunian","text":"你以前只吃绿豆的。"},{"t":"n","text":"你接过来。冰棍化得很快，顺着木棍往下淌。"},{"t":"n","text":"假期结束，你坐上回学校的车。妈妈往你包里塞了一袋煮鸡蛋，还是热的。"},{"t":"n","text":"苏念来送你。她站在站台上，手里拎着一个纸袋。"},{"t":"c","id":"sunian","text":"路上吃。鸡蛋别放太久。"},{"t":"n","text":"你接过来。纸袋底下还有一包奶片。"},{"t":"n","text":"车来了。你上车，找到靠窗的位置。"},{"t":"n","text":"她站在站台上，没有挥手，只是看着。"},{"t":"n","text":"车开动的时候，她抬手，很快地摆了一下。"},{"t":"n","text":"你把纸袋抱在怀里。鸡蛋还是温的，隔着纸袋，烫着你的手心。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"陪家里人","hint":"留一晚给家 · 家庭 ↑","eff":{"familyRel":6.0,"happy":3.0,"stress":-2.0},"reply":[{"t":"n","text":"你陪妈妈把碗洗了，又陪爸爸看完了那档他每天都在看的节目。"},{"t":"n","text":"节目结束，他忽然说：「在外面，别太省。」"},{"t":"n","text":"你说知道。"},{"t":"n","text":"他点点头，把遥控器放回茶几上，位置和昨天一样。"},{"t":"n","text":"妈妈在厨房里喊：「西瓜切好了。」"},{"t":"n","text":"你走过去。她把最中间的那一块留给你，上面插着一根牙签。"}]},{"label":"B","text":"和苏念去看海","hint":"把旧约定兑现 · 她会记住","eff":{"aff":6.0,"happy":4.0,"promise":true},"reply":[{"t":"c","id":"sunian","text":"你高一说过要去看海。还算数吗？"},{"t":"n","text":"你们坐了两个小时的公交。海是灰的，风很大，她把外套帽子戴上，只露出一双眼睛。"},{"t":"c","id":"sunian","text":"比我想的冷。"},{"t":"n","text":"但她一直站到天黑。"},{"t":"n","text":"她从口袋里摸出两颗糖，给你一颗。糖纸被风吹走，她追了两步，没追到。"},{"t":"c","id":"sunian","text":"算了。"},{"t":"n","text":"她站在海边，把糖含在嘴里，腮帮子鼓了一小块。"},{"t":"n","text":"你们沿着河堤走到桥下。她说起班上的孩子，说起哪个学生把她的粉笔藏起来了。"},{"t":"n","text":"你听着，忽然觉得她好像已经走在了另一条路上。"},{"t":"n","text":"她说到一半，停下来。"},{"t":"c","id":"sunian","text":"你怎么不说话。"},{"t":"n","text":"你说你在听。"},{"t":"n","text":"她看了你一会儿，继续往前走。"}]},{"label":"C","text":"一个人回旧学校","hint":"和过去待一会儿 · 心情 ↑","eff":{"stress":-6.0,"happy":2.0},"reply":[{"t":"n","text":"学校进不去。你站在门口，看见操场边的梧桐又高了一截。"},{"t":"n","text":"保安问你找谁。你说，不找谁。"},{"t":"n","text":"你在门口站了一会儿。教学楼三楼的灯亮着，那是你以前的教室。"},{"t":"n","text":"你给苏念发了一条消息：「我在校门口。」"},{"t":"n","text":"她回得很快：「等我。」"},{"t":"n","text":"十分钟后，她骑着一辆旧自行车过来，车筐里放着两瓶汽水。"},{"t":"c","id":"sunian","text":"门卫李叔认得我。进去看看？"},{"t":"n","text":"你们在操场上走了一圈。跑道翻新过，草还是原来的草。"}]}]}],"flagEcho":[{"t":"n","text":"回去的路上，苏念忽然说：「那张车票，你还留着吗？」"},{"t":"n","text":"你说留着。"},{"t":"n","text":"她「嗯」了一声，没有再问。"},{"t":"c","id":"sunian","text":"那就好。别弄丢了。"},{"t":"n","text":"她说完，往前走了两步，又回头。"},{"t":"c","id":"sunian","text":"我不是怕你弄丢。我是怕你忘了。"}],"flagBackfill":[{"t":"n","text":"回去的路上，苏念从口袋里摸出一张车票，塞进你手心。"},{"t":"n","text":"是一张 12 路的票，新的，边角还是硬的。日期是今天。"},{"t":"c","id":"sunian","text":"上次那张，你没要。这张，别再弄丢了。"},{"t":"n","text":"你低头看票。起点是你家门口，终点是纺织厂。"},{"t":"c","id":"sunian","text":"毕业那天，你回来一趟。"},{"t":"n","text":"她说完就往前走，没有等你回答。"},{"t":"n","text":"你捏着那张票，站在原地。风把票的一角吹起来，又落下。"}],"id":"sn_13","canBackfill":"flag1"},{"no":14,"title":"她的毕业","week":41,"bg":"campus","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"她的毕业典礼在六月。你买了最早的一班车，还是晚点了四十分钟。"},{"t":"n","text":"出租车在校门口被保安拦下。你付了钱，跑进去。礼堂的门关着，里面在鼓掌。"},{"t":"n","text":"你从侧门进去，站在最后一排。"},{"t":"n","text":"台上站着苏念。学士服有点大，袖子盖住半个手背。她手里拿着一页纸，没有看。"},{"t":"c","id":"sunian","text":"……我实习的班上，有个孩子问我，老师，你为什么要当老师。"},{"t":"n","text":"她的声音很稳。礼堂里很安静。"},{"t":"c","id":"sunian","text":"我说，因为我小时候遇到过一个老师。她教我写的第一个字，是『人』。她说，一撇一捺，要互相撑着。"},{"t":"n","text":"她停了一下。目光从台下扫过去，扫到最后一排。"},{"t":"n","text":"她看见了你。话停了半秒。"},{"t":"c","id":"sunian","text":"……我一直记得。"},{"t":"n","text":"她低下头，看了一眼手里的纸，又抬起来。"},{"t":"c","id":"sunian","text":"后来我明白了。不是我去撑谁。是那些孩子，让我站得住。"},{"t":"n","text":"她鞠了一躬。掌声响起来。"},{"t":"n","text":"典礼结束，人从礼堂里涌出来。你站在梧桐树下等。"},{"t":"n","text":"她出来的时候，学士帽拿在手里，头发被压得有点塌。"},{"t":"n","text":"她看见你，脚步快了一点，又慢下来。"},{"t":"c","id":"sunian","text":"你来了。"},{"t":"n","text":"你说你来了。"},{"t":"c","id":"sunian","text":"我以为你赶不上。"},{"t":"n","text":"她走到你面前，站定。学士服的领口有点歪，她伸手理了理，没有理好。"},{"t":"n","text":"校门口停着一辆 12 路。车门开着，她爸爸坐在驾驶室，胳膊搭在车窗上。"},{"t":"npc","name":"苏念妈妈","text":"念念！这儿！"},{"t":"n","text":"她回头看了你一眼。"},{"t":"c","id":"sunian","text":"你等我一下。我拍张照。"},{"t":"n","text":"她跑过去。她妈妈把花塞给她，她爸爸从车上下来，学士服和蓝衬衫站在一起，有一点不搭。"},{"t":"n","text":"苏念笑了。她爸爸站在旁边，手不知道往哪儿放，最后插进了裤兜。"},{"t":"n","text":"陈老师也来了，坐在树荫下，头发全白了。"},{"t":"n","text":"苏念拍完照，走过去，蹲在陈老师面前。"},{"t":"n","text":"陈老师摸了摸她的学士帽，说了两个「好」，没有再说别的。"},{"t":"n","text":"这时候，一个小男孩从人群里挤过来，手里攥着一把野花，花茎上还有泥。"},{"t":"n","text":"他跑到苏念面前，站住，把花举起来。"},{"t":"npc","name":"小宇","text":"苏老师。"},{"t":"n","text":"苏念愣了一下，蹲下去。"},{"t":"c","id":"sunian","text":"你怎么来了。"},{"t":"n","text":"小宇不说话，把花往她怀里塞。花是路边摘的，有黄的，有白的，用一根橡皮筋捆着。"},{"t":"n","text":"苏念接过来，低头看了很久。"},{"t":"c","id":"sunian","text":"谢谢。"},{"t":"n","text":"她的声音有点哑。小宇的奶奶站在后面，冲她点点头。"},{"t":"n","text":"你站在几步外，手里拿着一个纸袋。里面是一支钢笔，和一本硬壳的教案本。"},{"t":"n","text":"你本来想好了一句话。四年前那张车票，你一直留着。"},{"t":"n","text":"她爸爸的车先开走了。她妈妈坐在副驾，从车窗里冲你们摆手。"},{"t":"n","text":"林小满说要去买水，也走了。校门口安静下来。"},{"t":"n","text":"苏念低头把学士服的袖子卷起来。"},{"t":"c","id":"sunian","text":"红星小学。四年级。下周报到。"},{"t":"n","text":"你问她远不远。"},{"t":"c","id":"sunian","text":"坐 12 路到底，再走十分钟。城郊。班上四十二个孩子。"},{"t":"n","text":"她说这些的时候，眼睛是亮的。"},{"t":"n","text":"你想起四年前，她站在校门口，说「本城师范，小学教育」。"},{"t":"n","text":"那时候她的眼睛也是亮的，但没有现在这么稳。"},{"t":"n","text":"她把学士帽戴上，帽穗扫过眉毛。"},{"t":"c","id":"sunian","text":"你什么时候走。"},{"t":"n","text":"你说晚上的车。"},{"t":"n","text":"她点点头，从包里摸出一样东西，塞给你。"},{"t":"n","text":"是一枚校徽。师范大学的，蓝底白字，背面有一根别针。"},{"t":"c","id":"sunian","text":"拿着。别弄丢了。"},{"t":"n","text":"你把它别在衣服内侧。针穿过布料的时候，她伸手帮你扶了一下。"},{"t":"n","text":"她的手指很凉。"},{"t":"c","id":"sunian","text":"下次别赶末班车。"},{"t":"n","text":"她说完，转身往校门口走。学士服的下摆被风掀起来，像一面不太合身的旗。"},{"t":"n","text":"你站在梧桐树下，看着她走远。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把话说一半","hint":"让她知道你没忘","eff":{"aff":6.0,"happy":4.0,"stress":-2.0},"reply":[{"t":"n","text":"你走过去，说：「四年前那张票，我一直留着。」"},{"t":"n","text":"她抱着花，抬头看你。"},{"t":"n","text":"风把她的学士帽吹得歪了一下，她伸手按住。"},{"t":"c","id":"sunian","text":"我知道。"},{"t":"n","text":"你说，你还没说完。"},{"t":"n","text":"她笑了一下。"},{"t":"c","id":"sunian","text":"那就别说完了。说完了，就没意思了。"},{"t":"n","text":"她低头闻了闻那束野花，皱了皱鼻子。"},{"t":"c","id":"sunian","text":"有泥。"},{"t":"n","text":"但她没有放下。"}]},{"label":"B","text":"只把礼物递过去","hint":"把话留在心里","eff":{"aff":4.0,"happy":3.0,"stress":1.0},"reply":[{"t":"n","text":"你把纸袋递过去。她接过来，打开看了一眼。"},{"t":"c","id":"sunian","text":"钢笔？"},{"t":"n","text":"你说，还有教案本。"},{"t":"n","text":"她把教案本拿出来，翻开。扉页上你写了一行字：「给苏老师。」"},{"t":"n","text":"她看了很久，合上。"},{"t":"c","id":"sunian","text":"字还是这么丑。"},{"t":"n","text":"她说着，把教案本抱在怀里，和那束野花放在一起。"}]},{"label":"C","text":"先走，去车站","hint":"把位置留给她","eff":{"aff":1.0,"happy":-1.0,"stress":2.0},"reply":[{"t":"n","text":"你把纸袋放在她脚边，说你先走了。"},{"t":"n","text":"她愣了一下。"},{"t":"c","id":"sunian","text":"你不吃饭？"},{"t":"n","text":"你说车快开了。"},{"t":"n","text":"她看着你，没有挽留。"},{"t":"c","id":"sunian","text":"那你路上小心。"},{"t":"n","text":"你转身往校门口走。走了十几米，听见身后有人喊你的名字。"},{"t":"n","text":"你回头。她抱着花和纸袋，站在梧桐树下。"},{"t":"c","id":"sunian","text":"到了说一声！"}]}]}],"id":"sn_14"}]},{"id":"ch3","title":"第三章 · 职场","scenes":[{"no":15,"title":"第一份工作","week":44,"bg":"bedroom_night","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"你入职的第一周，工位还没坐热，群里的消息已经到了九十九加。"},{"t":"n","text":"出租屋在城中村，六楼，没有电梯。窗户对着另一栋楼的墙，白天也要开灯。"},{"t":"n","text":"你买了一张折叠桌，一把椅子，一个电饭锅。锅是二手的，内胆有一道划痕。"},{"t":"n","text":"晚上十点，苏念打来视频。她那边背景是白的，像办公室。"},{"t":"c","id":"sunian","text":"你猜我今天改了多少本作业。"},{"t":"n","text":"你说三十本。"},{"t":"c","id":"sunian","text":"四十二本。一本一本改。作文本，周记本，生字本。"},{"t":"n","text":"她把镜头转了一下。桌上摞着三摞本子，旁边是一杯凉了的茶。"},{"t":"n","text":"镜头转回来，她的眼睛下面有一点青。"},{"t":"c","id":"sunian","text":"我算过了。房租八百，吃饭六百，交通一百五。工资三千二百八。还能剩七百。"},{"t":"n","text":"她说得很认真，像在念一份报表。"},{"t":"c","id":"sunian","text":"我外婆说，当老师穷。我以前不信。"},{"t":"n","text":"她笑了一下。"},{"t":"c","id":"sunian","text":"现在信了一半。"},{"t":"n","text":"你问她剩下的一半呢。"},{"t":"c","id":"sunian","text":"剩下一半，是今天小宇考了九十二分。"},{"t":"n","text":"她把一张试卷举到镜头前。卷面很干净，右上角用红笔写着「92」，旁边画了一朵小红花。"},{"t":"c","id":"sunian","text":"他上次考五十八。这次作文写了三百字，没跑题。"},{"t":"n","text":"她说这话的时候，声音比刚才高了一点。"},{"t":"n","text":"你那边，电脑右下角的时间跳到十点二十。组长在群里发了一条「今晚辛苦，明早九点过方案」。"},{"t":"n","text":"你拿起桌上的饼干，咬了一口。包装袋在安静的房间里的响。"},{"t":"c","id":"sunian","text":"你在吃什么。"},{"t":"n","text":"你说饼干。"},{"t":"c","id":"sunian","text":"晚饭呢。"},{"t":"n","text":"你说吃了。"},{"t":"n","text":"她看着镜头，没有说话。"},{"t":"c","id":"sunian","text":"你嘴边有饼干渣。"},{"t":"n","text":"视频挂了以后，你看见微信里有一笔转账。二十块，备注：「买个饭。」"},{"t":"n","text":"你没有收。"},{"t":"n","text":"二十四小时后，钱自动退了回去。"},{"t":"n","text":"她发来一条消息：「你怎么不收。」"},{"t":"n","text":"你回：「我有。」"},{"t":"n","text":"她回了一个句号。"},{"t":"n","text":"过了一会儿，又发来一条：「明天记得。」"},{"t":"n","text":"第二天晚上，你下班路过便利店，买了一个饭团。你拍了张照发给她。"},{"t":"n","text":"她回了一个「好」字，后面跟着一朵小红花。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"老实说没吃","hint":"瞒不过她","eff":{"aff":5.0,"stress":-3.0,"happy":2.0},"reply":[{"t":"n","text":"你说，没吃。来不及。"},{"t":"n","text":"她把手机架在桌上，站起来。你听见她拖鞋在地板上走的声音。"},{"t":"c","id":"sunian","text":"你那儿有鸡蛋吗。"},{"t":"n","text":"你说有。"},{"t":"c","id":"sunian","text":"煮两个。水开了再放，六分钟。"},{"t":"n","text":"你拿着手机去厨房。她在镜头里看着你接水，开火，放鸡蛋。"},{"t":"c","id":"sunian","text":"你盐放了没有。"},{"t":"n","text":"你说忘了。"},{"t":"c","id":"sunian","text":"现在放。一点点。"},{"t":"n","text":"你把盐撒进去。她在那边点点头。"},{"t":"c","id":"sunian","text":"行了。等吧。"},{"t":"n","text":"你就站在锅边，和她聊了六分钟。她说她班上有个孩子，把「熊」字写成了「能」，还理直气壮。"},{"t":"n","text":"鸡蛋熟了。你捞出来，过了一下凉水。"},{"t":"c","id":"sunian","text":"吃吧。我看着。"},{"t":"n","text":"你剥了一个，咬了一口。蛋黄有点干。"},{"t":"c","id":"sunian","text":"熟过头了。下次五分钟。"}]},{"label":"B","text":"说吃了","hint":"先把今晚熬过去","eff":{"aff":1.0,"stress":1.0,"happy":-1.0},"reply":[{"t":"n","text":"你说吃了。楼下买的炒饭。"},{"t":"n","text":"她「哦」了一声。"},{"t":"c","id":"sunian","text":"那行。你忙吧。"},{"t":"n","text":"你说明天再聊。她说好。"},{"t":"n","text":"挂了视频，房间里一下子安静下来。电脑的风扇在响。"},{"t":"n","text":"你继续改方案。改到十二点，胃开始疼。"},{"t":"n","text":"你翻抽屉，找出半包饼干，吃完了。"},{"t":"n","text":"手机亮了一下。她发来一条消息：「你那儿有鸡蛋吗。」"},{"t":"n","text":"你回：「有。」"},{"t":"n","text":"她回：「煮两个。别光吃饼干。」"}]},{"label":"C","text":"反问她班上怎么样","hint":"先听她说","eff":{"aff":4.0,"happy":2.0,"stress":-1.0},"reply":[{"t":"n","text":"你问她，小宇最近怎么样。"},{"t":"n","text":"她愣了一下，然后坐回椅子上。"},{"t":"c","id":"sunian","text":"今天他把同桌的铅笔盒碰掉了，两个人吵了一架。我让他们互相道歉，他不肯。"},{"t":"n","text":"她说着，拿起桌上的红笔，转了一圈。"},{"t":"c","id":"sunian","text":"后来我问他，为什么不肯。他说，他先碰掉的，但他不是故意的。同桌说他是故意的。"},{"t":"n","text":"她看着镜头。"},{"t":"c","id":"sunian","text":"我说，那你就说『我不是故意的』。他说了。同桌也说了。两个人就好了。"},{"t":"n","text":"她说完，叹了口气。"},{"t":"c","id":"sunian","text":"我有时候觉得，我教的不是语文。是怎么跟人说话。"},{"t":"n","text":"你说这挺难的。"},{"t":"c","id":"sunian","text":"难。但比改作文有意思。"}]}]}],"id":"sn_15"},{"no":16,"title":"家长的电话","week":47,"bg":"office_day","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"电话来的时候，你正在会议室门口等。里面的人在调投影，白墙上晃着一片蓝。"},{"t":"n","text":"你走到楼梯间接。楼道里的灯是声控的，你跺了一下脚，灯亮了。"},{"t":"c","id":"sunian","text":"你在忙吗。"},{"t":"n","text":"你说还好。"},{"t":"n","text":"她沉默了两秒。"},{"t":"c","id":"sunian","text":"有个家长投诉我。"},{"t":"n","text":"她把事情说了一遍。班上有个孩子作业没写完，她让他课间补。孩子回家说，老师罚他站了一节课。"},{"t":"n","text":"家长第二天来了学校，在办公室门口说了很久。"},{"t":"c","id":"sunian","text":"我没让他站。我让他坐在我旁边的椅子上补。"},{"t":"n","text":"她的声音很稳，稳得不太正常。"},{"t":"c","id":"sunian","text":"校长让我写个说明。三百字就行。我写了三页。"},{"t":"n","text":"你听见纸翻动的声音。"},{"t":"c","id":"sunian","text":"写完我自己看了一遍，觉得像在辩解。"},{"t":"n","text":"会议室的门开了，同事探出头，冲你比了个手势。你摆摆手。"},{"t":"n","text":"她继续说。"},{"t":"c","id":"sunian","text":"李老师替我说了话。她说那个孩子平时就爱告状。但校长说，家长那边要安抚。"},{"t":"n","text":"她停了一下。"},{"t":"c","id":"sunian","text":"我今天站在讲台上，看着他们，忽然觉得……我可能不适合当老师。"},{"t":"n","text":"这是她第一次这么说。"},{"t":"n","text":"你握着手机，楼梯间的灯灭了。你没有跺脚。"},{"t":"c","id":"sunian","text":"你别不说话。"},{"t":"n","text":"你说你在。"},{"t":"n","text":"她「嗯」了一声。"},{"t":"c","id":"sunian","text":"我就说说。说完就好了。"},{"t":"n","text":"第二天中午，她发来一张照片。"},{"t":"n","text":"一本作业本，摊开在办公桌上。字写得歪歪扭扭，最后一行是：「苏老师，我补完了。」"},{"t":"n","text":"封面上画着一个太阳，太阳有眼睛和嘴。"},{"t":"c","id":"sunian","text":"小宇补完了。他妈妈也来了，跟我道了歉。"},{"t":"c","id":"sunian","text":"我没事了。"},{"t":"n","text":"你看着那张照片，看了很久。"},{"t":"n","text":"照片的角落里，露出她那只旧保温杯，杯盖上贴着一张小红花贴纸。"},{"t":"n","text":"你回了一个「好」。想了想，又加了一句：「你适合。」"},{"t":"n","text":"她没有回。过了一会儿，头像亮了一下，又暗了。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把会议推掉，去她的城市","hint":"这次先到她身边","eff":{"aff":6.0,"stress":3.0,"fin":-4.0,"happy":3.0},"reply":[{"t":"n","text":"你回会议室，跟组长说家里有急事。他看了你一眼，说：「明天九点前把方案发我。」"},{"t":"n","text":"你买了最近的一班车。到她学校时，天已经黑了。"},{"t":"n","text":"她坐在校门口的花坛边，膝盖上放着那三页说明。"},{"t":"n","text":"看见你，她愣了很久。"},{"t":"c","id":"sunian","text":"你怎么来了。"},{"t":"n","text":"你说来看看。"},{"t":"n","text":"她低下头，把说明折起来，又展开。"},{"t":"c","id":"sunian","text":"你不用来的。我都处理好了。"},{"t":"n","text":"她说完，眼泪掉下来，砸在纸上，晕开一小块。"},{"t":"n","text":"她很快擦掉，抬头看你。"},{"t":"c","id":"sunian","text":"你别看。"},{"t":"n","text":"你在她旁边坐下。花坛里有蚊虫，绕着路灯转。"},{"t":"n","text":"她把头靠在你的肩膀上，很轻，像怕压疼你。"}]},{"label":"B","text":"在楼梯间陪她打完这个电话","hint":"先听她把话说完","eff":{"aff":5.0,"stress":-2.0,"happy":2.0},"reply":[{"t":"n","text":"你说，你听着。慢慢说。"},{"t":"n","text":"她就真的慢慢说。从那个孩子说到家长，从家长说到校长，从校长说到李老师。"},{"t":"n","text":"说到最后，她自己笑了。"},{"t":"c","id":"sunian","text":"我是不是很啰嗦。"},{"t":"n","text":"你说不啰嗦。"},{"t":"n","text":"她沉默了一会儿。"},{"t":"c","id":"sunian","text":"其实我知道我没做错。我就是……有点累。"},{"t":"n","text":"你说，那就累一会儿。"},{"t":"n","text":"她「嗯」了一声。"},{"t":"n","text":"过了一会儿，她说：「你回去开会吧。我没事了。」"},{"t":"n","text":"你说不急。"},{"t":"c","id":"sunian","text":"急。你们那个组长，看着就不好说话。"}]},{"label":"C","text":"说「我晚点打给你」","hint":"先把眼前的事做完","eff":{"aff":-4.0,"stress":2.0,"happy":-2.0},"reply":[{"t":"n","text":"你说，你先进去开个会，晚点打给她。"},{"t":"n","text":"她停了一下。"},{"t":"c","id":"sunian","text":"好。你忙。"},{"t":"n","text":"挂了电话，你回到会议室。投影已经调好了，白墙上是一张流程图。"},{"t":"n","text":"你坐下，听见组长在说话。你一个字也没听进去。"},{"t":"n","text":"会开到八点半。你出来，给她打电话。响了很久，没有人接。"},{"t":"n","text":"你又打了一个。她接了。"},{"t":"c","id":"sunian","text":"我刚在洗澡。"},{"t":"n","text":"你问她说明写了没有。"},{"t":"c","id":"sunian","text":"写了。交了。"},{"t":"c","id":"sunian","text":"你开会开完了？"},{"t":"n","text":"你说开完了。"},{"t":"c","id":"sunian","text":"那就好。"}]}]}],"id":"sn_16"},{"no":17,"title":"深谈（Flag2）","week":49,"bg":"bedroom_night","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"她来你的城市开会。省里的乡村教师培训，三天，住在城东的一家快捷酒店。"},{"t":"n","text":"会开完了，她多留了一晚。"},{"t":"n","text":"你下班赶过去，已经八点半。她在大堂等你，穿着那件旧羽绒服，袖口磨得有点起球。"},{"t":"n","text":"她手里拎着一个会议资料袋，袋子上印着「小学语文整本书阅读」。"},{"t":"c","id":"sunian","text":"你瘦了。"},{"t":"n","text":"你说她也是。"},{"t":"c","id":"sunian","text":"我那是晒的。城郊风大。"},{"t":"n","text":"她站起来，把资料袋换到另一只手。"},{"t":"c","id":"sunian","text":"走走吧。你们这儿，我还没逛过。"},{"t":"n","text":"你们在路口找了一家便利店。她买了两罐热咖啡，你要付钱，她先扫了码。"},{"t":"n","text":"你们坐在路边的长椅上。椅子是铁的，凉。她隔着羽绒服坐下，把咖啡罐在手里捂着。"},{"t":"c","id":"sunian","text":"你这里，晚上比我们那儿亮。"},{"t":"n","text":"她仰头看了一会儿楼。写字楼的灯一层一层，亮到很高的地方。"},{"t":"c","id":"sunian","text":"我们那儿，八点半路上就没人了。十点以后，只有路灯。"},{"t":"n","text":"她把咖啡罐打开，热气冒出来，很快散了。"},{"t":"c","id":"sunian","text":"我今天在会上发言了。讲整本书阅读。台下有一百多个人，还有几个特级教师。"},{"t":"n","text":"你问她紧张没有。"},{"t":"c","id":"sunian","text":"紧张。上台前去了三趟厕所。"},{"t":"n","text":"她笑了一下。"},{"t":"c","id":"sunian","text":"讲完了，有个老师来加我微信，说想看看我们班的读书笔记。"},{"t":"c","id":"sunian","text":"我从来没觉得，自己讲的东西，有人想听。"},{"t":"n","text":"安静了一会儿。她低下头，看着手里的咖啡罐。"},{"t":"c","id":"sunian","text":"中心校想调我过去。校长跟我谈了两次。"},{"t":"n","text":"你问她去不去。"},{"t":"c","id":"sunian","text":"不知道。红星小学那帮孩子，我刚带顺。小宇的作文才写到三百字，我走了，换个老师，他可能又不写了。"},{"t":"c","id":"sunian","text":"但我妈说，人往高处走。"},{"t":"n","text":"她把咖啡罐在手里转了半圈。"},{"t":"c","id":"sunian","text":"我妈还给我安排了一个相亲。上个月的事。对方开诊所的，人挺客气。"},{"t":"n","text":"你问她去了没有。"},{"t":"c","id":"sunian","text":"去了。吃了半顿饭。"},{"t":"n","text":"她笑了一声。"},{"t":"c","id":"sunian","text":"他问我，一个本科生，在村小图什么。"},{"t":"n","text":"她抬起头，看着对面的楼。"},{"t":"c","id":"sunian","text":"我没回答。回来路上买了个烤红薯，站在路边吃完了。"},{"t":"n","text":"风大了一点。她把羽绒服的拉链往上拉，拉到下巴。"},{"t":"c","id":"sunian","text":"我今年存了四万。再存两年，能付个小房子的首付。我连窗帘都看好了，米色的，遮光。"},{"t":"n","text":"她说这些的时候，语气很平，像在说别人的事。"},{"t":"n","text":"然后她停住了。"},{"t":"c","id":"sunian","text":"我妈问我，到底在等什么。"},{"t":"n","text":"你没有接话。"},{"t":"c","id":"sunian","text":"我跟她说，我没在等。"},{"t":"n","text":"她把咖啡罐在手里转了半圈。"},{"t":"c","id":"sunian","text":"我只是……想知道你过得好不好。这句话，从高中想到现在。"},{"t":"n","text":"风把她的头发吹起来。她伸手按住，动作和很多年前一样。"},{"t":"c","id":"sunian","text":"你别有压力。我说完就舒服了。"},{"t":"n","text":"她喝了一口。"},{"t":"c","id":"sunian","text":"苦。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把话接住","hint":"这一次别再让她等","eff":{"aff":10.0,"happy":6.0,"flag2":true,"lover":true},"reply":[{"t":"n","text":"你说，你过得不好。"},{"t":"n","text":"她转过头。"},{"t":"n","text":"你说，你每天加班到很晚。回去的路上，整栋楼只有你那扇窗是黑的。"},{"t":"n","text":"你说，你有时候会想，如果她在，会不会留一盏灯。"},{"t":"n","text":"她听完，很久没有说话。"},{"t":"c","id":"sunian","text":"那你早说啊。"},{"t":"n","text":"她的眼泪掉下来，砸在咖啡罐上，响了一声。"},{"t":"n","text":"她没有擦。她把罐子放在脚边，双手放在膝盖上，看着自己的手。"},{"t":"c","id":"sunian","text":"我以为你过得挺好的。你朋友圈里，都是好的。"},{"t":"n","text":"你说，朋友圈都是挑着发的。"},{"t":"n","text":"她笑了一下，眼泪还挂着。"},{"t":"c","id":"sunian","text":"我知道。我也是。"},{"t":"n","text":"你伸手，把她的手从膝盖上拿起来。她的手很凉，指尖有红笔印。"},{"t":"n","text":"她没有抽回去。"},{"t":"c","id":"sunian","text":"你想清楚了吗。我不是让你今天可怜我。"},{"t":"n","text":"你说你想清楚了。"},{"t":"n","text":"她看了你很久。久到你把她的手指一根一根握住。"},{"t":"c","id":"sunian","text":"那你不许反悔。"},{"t":"n","text":"你说不反悔。"},{"t":"n","text":"她低下头，额头抵在你的肩膀上。羽绒服的布料很凉，她的呼吸是热的。"},{"t":"n","text":"你抬手，揽住她的肩。她瘦了，肩胛骨硌手。"},{"t":"n","text":"过了一会儿，她闷闷地说了一句。"},{"t":"c","id":"sunian","text":"咖啡凉了。"},{"t":"n","text":"你说再买一罐。"},{"t":"c","id":"sunian","text":"不用。这罐我还没喝完。"},{"t":"n","text":"你们坐到便利店关灯。店员出来倒垃圾，看了你们一眼，没有催。"},{"t":"n","text":"她把手套摘下来，塞给你。"},{"t":"c","id":"sunian","text":"你手凉。戴着。"},{"t":"n","text":"你说她明天早上更冷。"},{"t":"c","id":"sunian","text":"我上车就暖和了。"},{"t":"n","text":"她说完，站起来，拍了拍羽绒服的下摆。"},{"t":"c","id":"sunian","text":"我明天六点的高铁。你别来送。"},{"t":"n","text":"你问她为什么。"},{"t":"c","id":"sunian","text":"太早了。你起不来。"},{"t":"n","text":"你说明天一定起得来。"},{"t":"n","text":"她看着你，笑了一下。"},{"t":"c","id":"sunian","text":"那你来。迟到不等。"},{"t":"n","text":"你送她到酒店门口。她进去之前，回头看了你一眼。"},{"t":"c","id":"sunian","text":"手套明天还我。"},{"t":"n","text":"你说好。"},{"t":"n","text":"她进去了。你站在门口，把手套戴上。手套有点小，指缝里还留着她的温度。"},{"t":"n","text":"回出租屋的路上，你路过一家便利店。灯很亮，收银台后面的人在打哈欠。"},{"t":"n","text":"你进去买了一罐咖啡。热的，甜的。"},{"t":"n","text":"站在门口喝了一口，太甜了。"},{"t":"n","text":"你想起她说「下次买甜的」，站在那儿，把一罐咖啡慢慢喝完。"},{"t":"n","text":"回到家，你没有开灯。窗外对面楼的灯亮着，一格一格。"},{"t":"n","text":"你摸黑走到窗边，看见玻璃上自己的影子。"}]},{"label":"B","text":"说「我很好」，然后送她回酒店","hint":"温柔地退一步","eff":{"aff":-2.0,"happy":-2.0,"stress":2.0},"reply":[{"t":"n","text":"你说你很好。工作稳定，住得也习惯。"},{"t":"n","text":"她看了你一会儿，点点头。"},{"t":"c","id":"sunian","text":"那就好。"},{"t":"n","text":"她站起来，把没喝完的咖啡扔进垃圾桶。罐子碰到桶底，响了一声。"},{"t":"n","text":"回酒店的路不远。你们并排走，谁也没有说话。"},{"t":"n","text":"到门口，她停下来。"},{"t":"c","id":"sunian","text":"你回去吧。明天还要上班。"},{"t":"n","text":"你说送她上去。"},{"t":"c","id":"sunian","text":"不用。前台认得我。"},{"t":"n","text":"她往里走了两步，又回头。"},{"t":"c","id":"sunian","text":"咖啡好苦。下次买甜的。"},{"t":"n","text":"你说好。"},{"t":"n","text":"她进去了。玻璃门合上，把里面的暖气隔在里面。"},{"t":"n","text":"你站在门口，看见她走到电梯前，按了按钮。"},{"t":"n","text":"她没有回头。"}]},{"label":"C","text":"沉默","hint":"什么都不说 · 她不会追问","eff":{"aff":-5.0,"happy":-4.0,"stress":3.0},"reply":[{"t":"n","text":"你什么也没说。"},{"t":"n","text":"她也没有再问。"},{"t":"n","text":"你们坐在长椅上，看着马路。车不多，一辆一辆过去。"},{"t":"n","text":"过了很久，她站起来，把空罐子扔进垃圾桶。"},{"t":"c","id":"sunian","text":"走吧，送你到地铁口。"},{"t":"n","text":"你说不用。"},{"t":"c","id":"sunian","text":"顺路。我酒店就在前面。"},{"t":"n","text":"你们走到地铁口。她站在台阶上面，你站在下面。"},{"t":"c","id":"sunian","text":"你回去吧。"},{"t":"n","text":"你说明天有空的话，可以一起吃个饭。"},{"t":"c","id":"sunian","text":"明天一早的高铁。六点。"},{"t":"n","text":"你说那下次。"},{"t":"n","text":"她点点头。"},{"t":"c","id":"sunian","text":"下次。"},{"t":"n","text":"你下了台阶。刷卡进站的时候，你回头看了一眼。"},{"t":"n","text":"她已经走了。"}]}]}],"id":"sn_17"},{"no":18,"title":"便当凉了","week":53,"bg":"bedroom_night","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"你加班到十点。出电梯的时候，楼道里的灯坏了一盏，一闪一闪。"},{"t":"n","text":"门口放着一个保温袋。蓝色的，拉链上挂着一只小木马挂件。"},{"t":"n","text":"便当已经凉了。旁边贴着一张便签：「热两分钟。不许不吃。」"},{"t":"n","text":"便签背面，画了一个很丑的笑脸。笑脸的嘴画歪了，一直咧到耳朵。"},{"t":"n","text":"你把保温袋拎进屋。饭盒是满的，土豆烧牛肉，青椒炒蛋，米饭上撒了芝麻。"},{"t":"n","text":"你把它放进微波炉，按了两分钟。"},{"t":"n","text":"等待的时候，你看见袋子里还有一张超市小票。日期是今天，下午六点。买的是牛肉、青椒、鸡蛋，还有一板奶片。"},{"t":"n","text":"微波炉响了。你端出来，坐在折叠桌前。"},{"t":"n","text":"饭吃了一半，电话来了。"},{"t":"c","id":"sunian","text":"吃了吗。"},{"t":"n","text":"你说在吃。"},{"t":"c","id":"sunian","text":"热了没有。"},{"t":"n","text":"你说热了。"},{"t":"n","text":"她「嗯」了一声。那头有翻纸的声音。"},{"t":"c","id":"sunian","text":"我明天有公开课。中心校的人来听。"},{"t":"n","text":"你问她讲什么。"},{"t":"c","id":"sunian","text":"《爬山虎的脚》。我做了课件，还剪了爬山虎的叶子，塑封了，一人一片。"},{"t":"n","text":"她说着，声音里有一点兴奋。"},{"t":"c","id":"sunian","text":"就是不知道时间够不够。四十分钟，要讲完，还要留十分钟写作业。"},{"t":"n","text":"你说明天会顺利的。"},{"t":"n","text":"她笑了一下。"},{"t":"c","id":"sunian","text":"你声音不对。"},{"t":"n","text":"你说有点累。"},{"t":"c","id":"sunian","text":"你饭吃完了吗。"},{"t":"n","text":"你说快了。"},{"t":"n","text":"她沉默了几秒。"},{"t":"c","id":"sunian","text":"你站起来，走两步。"},{"t":"n","text":"你站起来，走了两步。眼前黑了一下，你扶住桌子。"},{"t":"n","text":"她没有听见声音，但她好像知道了。"},{"t":"c","id":"sunian","text":"你明天请假。"},{"t":"n","text":"你说请不了。明天要交方案。"},{"t":"c","id":"sunian","text":"那就后天。"},{"t":"n","text":"你说后天也不行。"},{"t":"n","text":"她在那头吸了一口气。"},{"t":"c","id":"sunian","text":"那我周末来。"},{"t":"n","text":"你说不用。你周末要补觉。"},{"t":"c","id":"sunian","text":"我不是来照顾你。"},{"t":"n","text":"她的声音很轻，但很稳。"},{"t":"c","id":"sunian","text":"我是来看看你还在不在。"},{"t":"n","text":"你没有说话。"},{"t":"n","text":"过了一会儿，她说：「你吃饭吧。我挂了。」"},{"t":"n","text":"挂断之前，她补了一句。"},{"t":"c","id":"sunian","text":"饭盒洗干净。下次我还要用。"},{"t":"n","text":"第二天早上，你把洗好的饭盒放在门口。"},{"t":"n","text":"晚上回来，饭盒不见了。门把上挂着一袋橘子，还有一板奶片。"},{"t":"n","text":"袋子上贴着一张便签：「饭盒我拿走了。橘子记得吃。」"},{"t":"n","text":"便签背面，还是那个很丑的笑脸。"},{"t":"n","text":"你站在门口，把橘子拎进屋。袋子很沉，大概有五六个。"},{"t":"n","text":"你剥了一个。有点酸。"},{"t":"n","text":"你还是吃完了。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把饭吃完，给她回电话","hint":"先让她听见你还好","eff":{"aff":5.0,"stress":-4.0,"happy":3.0},"reply":[{"t":"n","text":"你把剩下的饭吃完，连青椒都吃了。饭盒洗干净，倒扣在沥水架上。"},{"t":"n","text":"你给她回电话。她接得很快。"},{"t":"c","id":"sunian","text":"吃完了？"},{"t":"n","text":"你说吃完了。洗了。"},{"t":"n","text":"她「嗯」了一声。"},{"t":"c","id":"sunian","text":"拍张照我看看。"},{"t":"n","text":"你拍了。她看了几秒，说：「还行。没糊。」"},{"t":"n","text":"你听见她在那边笑。"},{"t":"c","id":"sunian","text":"我明天公开课，你要是没事，给我发个消息。就发『加油』两个字。"},{"t":"n","text":"你说好。"},{"t":"n","text":"第二天早上，你发了「加油」。她回了一张照片：黑板上写着「爬山虎的脚」，旁边画了一墙绿色的叶子。"},{"t":"n","text":"中午，她又发来一条：「讲完了。校长说，可以。」"},{"t":"n","text":"你回了一个「厉害」。她回了一朵小红花。"}]},{"label":"B","text":"发一条消息，不打电话","hint":"别让她听出疲惫","eff":{"aff":2.0,"stress":1.0,"happy":1.0},"reply":[{"t":"n","text":"你发了一条：「吃完了。好吃。」"},{"t":"n","text":"她回：「饭盒洗了吗。」"},{"t":"n","text":"你回：「洗了。」"},{"t":"n","text":"她发来一个「嗯」。"},{"t":"n","text":"过了一会儿，又发来一条：「你早点睡。别改方案了。」"},{"t":"n","text":"你回：「好。」"},{"t":"n","text":"你关掉电脑，躺在床上。天花板上有一道裂缝，你看了很久。"},{"t":"n","text":"手机亮了一下。她发来一张照片：一摞塑封的爬山虎叶子，摆在桌上。"},{"t":"c","id":"sunian","text":"明天一人一片。希望他们别弄丢。"}]},{"label":"C","text":"吃完继续改方案","hint":"先把明天交上去","eff":{"aff":-3.0,"stress":4.0,"happy":-2.0},"reply":[{"t":"n","text":"你把饭盒推到一边，打开电脑。"},{"t":"n","text":"方案改到十二点。改完，你站起来，眼前黑了一下，比刚才久。"},{"t":"n","text":"你扶着墙站了一会儿，才想起要呼吸。"},{"t":"n","text":"手机里有她的一条消息，十一点发的：「睡了吗。」"},{"t":"n","text":"你回：「刚忙完。」"},{"t":"n","text":"她没有再回。"},{"t":"n","text":"第二天早上，你看见她凌晨一点发的一条朋友圈，只有一张照片：剪好的爬山虎叶子，摆了一桌子。"},{"t":"n","text":"配的字是：「明天，加油。」"},{"t":"n","text":"你点了一个赞。想了想，又取消了。"}]}]}],"id":"sn_18"},{"no":19,"title":"十二路","week":57,"bg":"station","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"你回本城，是因为总部来了一纸调令。"},{"t":"n","text":"升职，去另一座城市，两年。工资涨四成，职级跳一级。"},{"t":"n","text":"傍晚，你坐 12 路到终点站。纺织厂的铁门还是锁着，站牌换了一块新的，「纺织厂」三个字印得很正。"},{"t":"n","text":"苏念从学校那边走过来。她穿着那件旧羽绒服，手里拎着两个纸袋。"},{"t":"n","text":"她在你旁边坐下，把其中一个纸袋递给你。"},{"t":"c","id":"sunian","text":"烤红薯。路边买的。"},{"t":"n","text":"你接过来。"},{"t":"c","id":"sunian","text":"你那个，凉一凉再吃。"},{"t":"n","text":"你们坐在长椅上。风从河面上吹过来，带着一点腥气。"},{"t":"n","text":"过了一会儿，她开口。"},{"t":"c","id":"sunian","text":"中心校的调令下来了。下学期。"},{"t":"n","text":"你问她去不去。"},{"t":"c","id":"sunian","text":"去。我想去。"},{"t":"c","id":"sunian","text":"红星小学那边，我带完这个学期。小宇的作文能写五百字了。我跟新老师交代好了。"},{"t":"c","id":"sunian","text":"我爸的腰，医生说不能再开了。车队给他调了调度。工资少一点，但不用坐一整天。"},{"t":"n","text":"她抬起头。"},{"t":"c","id":"sunian","text":"我妈想让我搬回老街住。我说再等等。"},{"t":"n","text":"你问她等什么。"},{"t":"n","text":"她没有马上回答。"},{"t":"n","text":"远处，12 路末班车从站台另一头开过来，停在终点。车灯亮着，驾驶室里的人不是她爸爸。"},{"t":"n","text":"她爸爸坐在最后一排，靠窗，穿着便服，手里拎着一个保温杯。"},{"t":"n","text":"他看见你们，抬了抬下巴，没有下车。"},{"t":"c","id":"sunian","text":"我爸今天最后一天。明天就交钥匙了。"},{"t":"n","text":"她的声音很轻。"},{"t":"c","id":"sunian","text":"他开了大半辈子。今天早上，他把车擦了一遍，擦了四十分钟。"},{"t":"n","text":"然后她转过身，看着你。"},{"t":"c","id":"sunian","text":"你那个调令，什么时候走。"},{"t":"n","text":"你说下个月。"},{"t":"n","text":"她点点头。"},{"t":"c","id":"sunian","text":"那挺好。升职。"},{"t":"n","text":"她说完，笑了一下。笑得不太用力。"},{"t":"n","text":"风把她的头发吹起来。她伸手按住。"},{"t":"c","id":"sunian","text":"你不用为我留下。我也不会为你留下。"},{"t":"n","text":"你说你没说要留下。"},{"t":"c","id":"sunian","text":"我知道。我先说。"},{"t":"n","text":"她看着你，眼睛很亮。"},{"t":"c","id":"sunian","text":"我这些年，不是在原地等你。我上课，改作业，存钱，相亲，被家长投诉，写说明。我过我的日子。"},{"t":"n","text":"她停了一下。"},{"t":"c","id":"sunian","text":"只是过日子的时候，会想起你。"},{"t":"c","id":"sunian","text":"所以你别觉得，你欠我什么。你走，我也不会垮。"},{"t":"n","text":"她伸出手，把你手里凉了的红薯拿过去，塞回纸袋。"},{"t":"c","id":"sunian","text":"但如果你要回来，我在。"},{"t":"n","text":"她说完，站起来，拍了拍裤子。"},{"t":"n","text":"12 路末班车发动了。车灯照过来，把你的影子拉得很长。"},{"t":"n","text":"她坐在靠窗的位置。车开动的时候，她把车窗推开一条缝，伸出手，摆了摆。"},{"t":"n","text":"你站在站台上，也摆了摆手。"},{"t":"n","text":"车开远了。终点站的灯还亮着，站牌上「纺织厂」三个字很清楚。"},{"t":"n","text":"口袋里的手机震了一下。她发来一条消息：「到了说一声。」"},{"t":"n","text":"你回：「好。」"},{"t":"n","text":"你站在站台上，没有立刻走。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"拒绝调令，回本城","hint":"把日子过回来","eff":{"aff":8.0,"happy":6.0,"stress":-4.0,"route":"stay"},"reply":[{"t":"n","text":"你说，你不去总部了。"},{"t":"n","text":"她愣住。"},{"t":"c","id":"sunian","text":"你想清楚。那是升职。"},{"t":"n","text":"你说想清楚了。升职还会有，有些东西不会有第二次。"},{"t":"n","text":"她看着你，看了很久。"},{"t":"c","id":"sunian","text":"你别是因为我今天说了这些。"},{"t":"n","text":"你说不是。你说你早就在想，只是今天才敢说。"},{"t":"n","text":"她低下头，把纸袋捏得皱起来。"},{"t":"c","id":"sunian","text":"那你回来，住哪儿。"},{"t":"n","text":"你说先租房子。"},{"t":"c","id":"sunian","text":"租哪儿。"},{"t":"n","text":"你说，离你学校近一点。"},{"t":"n","text":"她抬起头，眼睛红了，但没有哭。"},{"t":"c","id":"sunian","text":"我学校在城郊。房租便宜。就是远。"},{"t":"n","text":"你说远一点没关系。"},{"t":"n","text":"她「嗯」了一声。"},{"t":"c","id":"sunian","text":"那我帮你问。我们学校旁边有个小区，一室一厅，一千二。"}]},{"label":"B","text":"接受调令，去总部","hint":"去更大的地方","eff":{"aff":-21.0,"stress":4.0,"happy":-2.0,"route":"go"},"reply":[{"t":"n","text":"你说，你决定去。"},{"t":"n","text":"她点点头，像是早就知道。"},{"t":"c","id":"sunian","text":"什么时候走。"},{"t":"n","text":"你说下个月十号。"},{"t":"c","id":"sunian","text":"那还有一个月。"},{"t":"n","text":"她把纸袋抱在怀里。"},{"t":"c","id":"sunian","text":"走之前，来面馆吃碗面。我外婆念叨你。"},{"t":"n","text":"你说好。"},{"t":"n","text":"她站起来，往站台走。"},{"t":"c","id":"sunian","text":"两年。说长不长。"},{"t":"n","text":"她回头看了你一眼。"},{"t":"c","id":"sunian","text":"你要是回来，提前说一声。我去车站接你。"},{"t":"n","text":"你说好。"},{"t":"n","text":"她上了车。车门关上，她坐在靠窗的位置，没有再看你。"}]},{"label":"C","text":"先不承诺，各自走一段","hint":"把话留到以后","eff":{"aff":-10.0,"happy":-4.0,"stress":3.0,"route":"pause"},"reply":[{"t":"n","text":"你说，你不知道。"},{"t":"n","text":"她看着你，没有催。"},{"t":"n","text":"你说，你不想现在承诺，也不想让她等。"},{"t":"c","id":"sunian","text":"我没等。"},{"t":"n","text":"她说完，自己笑了一下。"},{"t":"c","id":"sunian","text":"行。我知道你的意思了。"},{"t":"n","text":"她站起来，把纸袋扔进垃圾桶。"},{"t":"c","id":"sunian","text":"那就先这样。你走你的，我过我的。"},{"t":"n","text":"她往站台走。走了几步，回头。"},{"t":"c","id":"sunian","text":"你别觉得对不起我。人各有各的路。"},{"t":"n","text":"她上了车。车门关上之前，她冲你摆了摆手，很轻。"}]}]}],"id":"sn_19"}]},{"id":"finale","title":"终章 · 三结局","scenes":[{"no":20,"title":"回到巷子","week":60,"bg":"campus_night","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"腊月二十八，你回本城。"},{"t":"n","text":"出租车停在巷口，司机说里面进不去，路太窄。你拎着箱子下来，脚下是青石板。"},{"t":"n","text":"梧桐还在。比小时候高了很多，枝丫伸到两边的屋顶上。叶子掉光了，剩几个干了的果球。"},{"t":"n","text":"小卖部还在，招牌换成了连锁超市的。门口堆着成箱的牛奶。"},{"t":"n","text":"你拎着箱子往里走。轮子在青石板上磕磕绊绊，声音很响。"},{"t":"n","text":"三楼的王阿姨在阳台上收衣服，看见你，愣了一下，说：「回来啦。」"},{"t":"n","text":"你说回来了。她点点头，把衣架往里收了收。"},{"t":"n","text":"楼道口的信箱上，她家的门牌还是 402，数字掉了一半漆。"},{"t":"n","text":"巷子两边的墙刷过一遍，又旧了。有人家在门上贴了春联，浆糊没有干，纸角翘着。"},{"t":"n","text":"你停在巷子中间，抬头看四楼那扇窗。风有点冷，天也是，巷子里很静。"},{"t":"n","text":"灯亮着。窗帘是米色的，遮光的那种。"},{"t":"n","text":"你想起她说过，她连窗帘都看好了。"},{"t":"n","text":"12 路从巷口经过。车换了新的，绿色的，没有售票员。驾驶室里的人低着头，你看不清。"},{"t":"n","text":"你把手伸进口袋，摸到那张车票。边角已经软得不像纸了。"},{"t":"n","text":"手机震了一下。"},{"t":"c","id":"sunian","text":"到了吗。"},{"t":"n","text":"你看着那三个字，看了一会儿。"},{"t":"n","text":"你回：「到了。」"},{"t":"n","text":"她回得很快。"},{"t":"c","id":"sunian","text":"上来吃饭。我妈包了饺子。"},{"t":"n","text":"你抬起头。四楼的窗帘动了一下。"},{"t":"n","text":"窗帘后面的人没有开窗，只是站着。你听见楼上有椅子挪动的声音，很轻。"},{"t":"n","text":"天黑透的时候，你站在巷口。"},{"t":"n","text":"四楼的灯还亮着。窗户开了一条缝，有热气从里面出来。"},{"t":"n","text":"你在楼下站了很久。你把箱子放在脚边。你把手从口袋里拿出来，掌心有一道车票的印子。"},{"t":"n","text":"你想起她十六岁那年，在站台上说「你试试」。想起她二十岁那年，在电话里说「你别来」。想起她二十四岁那年，在长椅上说「我没在等」。"},{"t":"n","text":"风从巷子里穿过来，带着别人家厨房的味道。"},{"t":"n","text":"手机又亮了。"},{"t":"c","id":"sunian","text":"饺子要凉了。"},{"t":"n","text":"你看着那行字。"},{"t":"n","text":"楼道里的声控灯亮起来，又灭了。有人从楼上下来，脚步声很轻。"},{"t":"n","text":"你抬起头。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"先坐 12 路到终点站","hint":"把这条路再走一遍","eff":{"happy":2.0,"stress":-2.0},"reply":[{"t":"n","text":"你把箱子寄放在楼下的小卖部，上了 12 路。"},{"t":"n","text":"车上人很少。你坐在最后一排，看窗外的店一家一家往后退。"},{"t":"n","text":"解放路。文化宫。老菜场。纺织厂。"},{"t":"n","text":"终点站的站牌换了新的。铁门还是锁着，里面的草长得很高。"},{"t":"n","text":"你在长椅上坐了一会儿。椅子也换了，不锈了。"},{"t":"n","text":"回去的车来了。你站起来，上了车。"}]},{"label":"B","text":"在巷口站一会儿","hint":"先不上去","eff":{"happy":1.0,"stress":-1.0},"reply":[{"t":"n","text":"你站在梧桐下面，没有动。"},{"t":"n","text":"四楼的窗帘又动了一下。有人走到窗边，往下看。"},{"t":"n","text":"你看不清她的脸，但知道是她。"},{"t":"n","text":"你抬起手，摆了摆。"},{"t":"n","text":"窗边的人没有摆手，只是站着。"},{"t":"n","text":"过了一会儿，楼道里的声控灯一层一层亮起来。"}]},{"label":"C","text":"去面馆的位置吃一碗面","hint":"先吃口热的","eff":{"happy":3.0,"familyRel":1.0},"reply":[{"t":"n","text":"苏记面馆的位置，现在是一家水果店。招牌拆了，墙上还留着一块颜色浅一点的印子。"},{"t":"n","text":"隔壁的馄饨店还开着。你进去，点了一碗荠菜馄饨。"},{"t":"n","text":"老板认得你，问：「苏家那个闺女，还当老师呢？」"},{"t":"n","text":"你说还当。"},{"t":"n","text":"他点点头，多给了你两个馄饨。"},{"t":"n","text":"「她外婆以前常来。坐那个位置。」他指了指靠窗的桌子。"}]}]}],"id":"sn_20","finaleEntry":true},{"no":21,"title":"结局一 · 陪你到最后","week":60,"bg":"home","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"你们结婚了。婚礼很小，只请了亲戚和几个朋友。"},{"t":"n","text":"在她家老街口的小饭店，八桌。她妈妈坚持要办，说一辈子就这一次。"},{"t":"n","text":"她爸爸穿了一身新西装，袖子长了一点，一直往上撸。他站在门口迎客，见人就递糖，自己不吃。"},{"t":"n","text":"林小满当伴娘，从南方飞回来。她抢到了捧花，举着满场跑。"},{"t":"n","text":"陈老师坐在主桌，穿一件浅灰色的衬衫。小宇也来了，已经上高中，个子蹿得很高，进门先喊「苏老师」。"},{"t":"n","text":"她穿了一件很简单的白裙子，头发还是半扎着，用一根奶白色的棉绳。"},{"t":"n","text":"没有请化妆师。林小满给她涂的口红，涂出界了一点。她对着手机前置摄像头擦了半天，没擦干净。"},{"t":"c","id":"sunian","text":"算了。反正也没人看。"},{"t":"n","text":"司仪问她有什么话想说。"},{"t":"n","text":"她想了很久。"},{"t":"c","id":"sunian","text":"也没什么。就是以后，你加班回来，我给你留灯。"},{"t":"n","text":"台下有人笑了。你也笑了，眼睛有点酸。"},{"t":"n","text":"司仪把话筒递给你。你事先没准备，站在那里，听见自己的心跳。"},{"t":"n","text":"你说：「我尽量早点回来。」"},{"t":"n","text":"她看着你，摇了摇头。"},{"t":"c","id":"sunian","text":"尽量不行。要说到做到。"},{"t":"n","text":"台下又笑了。你点头，说好。"},{"t":"n","text":"婚后的第一年，你们租在城郊，一室一厅。窗户朝西，下午很晒。"},{"t":"n","text":"她调进了中心校。每天早上六点起，坐 12 路，再走十分钟。"},{"t":"n","text":"你换了工作，不用天天加班。有时候还是晚，但会在路上给她发一条消息。"},{"t":"n","text":"玄关有一盏小灯，暖黄的，一直开着。"},{"t":"n","text":"一开始是她留。后来你回来得早，就先打开。"},{"t":"n","text":"很多年以后，你们搬了两次家。第一次是两室，第二次多了一个小房间。"},{"t":"n","text":"每次收拾东西，她都会把那张旧车票找出来，夹进同一本书里。"},{"t":"n","text":"那本书是《小学语文教学设计》，封面已经掉了，用透明胶粘着。"},{"t":"n","text":"你问她：「还留着？」"},{"t":"n","text":"她说：「留着。等老了翻出来看，就知道妈妈当年多傻。」"},{"t":"n","text":"后来那只小木马从书架上拿下来，放在你们的床头柜上。"},{"t":"n","text":"木马的一条腿又断过一次，她用胶粘好了，缠了一圈白线。"},{"t":"n","text":"她偶尔拿起来摇一下，摇得咯吱响。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把车票夹进她的教案本","hint":"让它跟着她上班","eff":{"happy":3.0},"reply":[{"t":"n","text":"你把那张车票从书里抽出来，夹进她第二天要用的教案本。"},{"t":"n","text":"夹在《秋天的雨》那一页。"},{"t":"n","text":"第二天晚上，她回来，把教案本放在桌上，没有提。"},{"t":"n","text":"但你看见，车票被移到了最后一页，用一张透明胶带贴住了边角。"}]},{"label":"B","text":"把木马放回床头柜","hint":"让它接着站","eff":{"happy":3.0,"familyRel":1.0},"reply":[{"t":"n","text":"你把木马擦干净，放回床头柜，面朝着门口。"},{"t":"n","text":"她在门口看着，说：「轻点。那是妈妈小时候的。」"},{"t":"n","text":"你把它摆正，那匹小木马在灯下站得稳稳的。"}]},{"label":"C","text":"关掉客厅的灯，留一盏玄关的灯","hint":"把灯留着","eff":{"happy":4.0},"reply":[{"t":"n","text":"你把客厅的灯关了，只留玄关那一盏。"},{"t":"n","text":"她还在书房改作业。门缝里透出一条光。"},{"t":"n","text":"你走过去，把一杯温水放在她手边。"},{"t":"n","text":"她头也没抬，说：「放那儿吧。」"},{"t":"n","text":"你回到卧室。过了一会儿，她进来，轻手轻脚。"},{"t":"c","id":"sunian","text":"灯我关了。"},{"t":"n","text":"你说留着吧。"}]}]}],"quality":{"high":["你们的日子很普通。普通到你有时候会忘记，这是自己选的。但每天回家，看见那盏灯，你就想起来了。","周末你们去菜市场，她挑西红柿，你拎袋子。她跟摊主讲价，讲了五毛，回头冲你笑。"],"mid":["你们也会为钱吵架，也会一整个晚上不说话。但第二天早上，她还是会给你煎一个鸡蛋。","蛋边煎焦了，她把好的那个夹到你碗里，自己吃焦的。你们谁也没提昨晚的事。"],"low":["你陪她的时间，比你想的少。她从来不说。你后来在她的手机备忘录里，看见一行字：「今天他又没回来吃饭。」","你往下翻，还有很多条，日期隔得很开，每一条后面都没有标点。"]},"id":"sn_21","ending":"stay"},{"no":22,"title":"结局二 · 我们曾在最好的年纪错过","week":60,"bg":"izakaya_night","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"你们没有在一起。"},{"t":"n","text":"不是不喜欢。是那时候的你们，都以为还有很多时间。"},{"t":"n","text":"后来她结婚了。请柬是你妈妈转交的，上面她的名字，印得很端正。"},{"t":"n","text":"你妈妈把请柬放在桌上，说：「她让我问你，来不来。」"},{"t":"n","text":"你说来。"},{"t":"n","text":"婚礼在县城的一家酒店，二十桌。门口摆着两张易拉宝，上面是他们的婚纱照。"},{"t":"n","text":"她丈夫是中学的物理老师，话不多，戴眼镜。敬酒的时候，他一直跟在她旁边，替她拿着外套。"},{"t":"n","text":"你坐在同学桌。林小满也在，穿了一件新裙子，头发烫过。"},{"t":"n","text":"桌上摆着瓜子和喜糖。喜糖是巧克力味的。你剥了一颗，糖纸捏在手里。你把糖纸叠成一个小方块，放进口袋里。台上在放他们的恋爱视频，配乐很响。"},{"t":"n","text":"婚礼进行到一半，她换了一身红色的敬酒服。头发盘起来，露出耳朵。"},{"t":"n","text":"她敬酒到你这桌，停了一下。"},{"t":"c","id":"sunian","text":"你来了。"},{"t":"n","text":"你说：「恭喜。」"},{"t":"n","text":"她点点头，去了下一桌。"},{"t":"n","text":"你坐下，端起杯子，喝了一口。是果汁，甜的。"},{"t":"n","text":"林小满在旁边说：「她昨天问我，你会不会来。」"},{"t":"n","text":"你问她怎么说的。"},{"t":"npc","name":"林小满","text":"我说会。你这个人，别的不行，场面上从来不掉链子。"},{"t":"n","text":"她说完，自己先笑了。笑完，叹了口气。"},{"t":"n","text":"散场的时候，你在酒店门口看见她站在台阶上。"},{"t":"n","text":"婚纱的裙摆被风吹起来。她伸手按住，动作和很多年前一样。"},{"t":"n","text":"她好像看见了你，又好像没有。"},{"t":"n","text":"你转身走进夜色里。"},{"t":"n","text":"后来你也有过别人。有一次差点结婚，最后没成。分手那天，你们吃了一顿很平静的饭。"},{"t":"n","text":"你后来过得不错。工作换了两座城市，房子买在一座有河的城市。"},{"t":"n","text":"你偶尔在同学群里看见她。她发教室、发学生的照片，你点一个赞。"},{"t":"n","text":"有一年春节，你回本城，路过老街。苏记面馆的位置换成了水果店。"},{"t":"n","text":"你在门口站了一会儿，买了两斤橘子。"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"把车票放进红包","hint":"把旧东西还回去","eff":{"happy":2.0,"stress":-2.0},"reply":[{"t":"n","text":"你在红包里放了礼金，又把那张旧车票放了进去。"},{"t":"n","text":"车票已经软得不像纸，你用一张便签包住，便签上什么也没写。"},{"t":"n","text":"红包交到签到台。收礼的姑娘看了一眼，把它放进了箱子。"},{"t":"n","text":"你不知道她后来有没有看见。"},{"t":"n","text":"你也没有问。"}]},{"label":"B","text":"帮她把裙摆理好","hint":"最后一次搭把手","eff":{"happy":3.0},"reply":[{"t":"n","text":"散场的时候，她的裙摆卡在台阶的缝里。她弯腰去拉，拉不动。"},{"t":"n","text":"你走过去，蹲下来，把纱从缝里一点一点抽出来。"},{"t":"n","text":"她低头看着你。"},{"t":"c","id":"sunian","text":"谢谢。"},{"t":"n","text":"你说不客气。"},{"t":"n","text":"这是你们那天说的最后一句话。"}]},{"label":"C","text":"提前离席","hint":"把位置留给她","eff":{"happy":1.0,"stress":-1.0},"reply":[{"t":"n","text":"你在敬酒之前就走了。"},{"t":"n","text":"酒店门口的服务员帮你叫了车。你站在路边等，风很大。"},{"t":"n","text":"车来了。你上车，报了一个地址。"},{"t":"n","text":"车开出去一段，你回头看了一眼。酒店的灯还亮着，门口的红毯没有收。"}]}]}],"quality":{"high":["你后来也过得不错。你只是偶尔会想，如果那天你说出口了，会怎么样。","想完，你继续过你的日子。有些人适合放在心里，不适合放在日子里。"],"mid":["你们偶尔在同学群里说话。她发教室、发学生的照片，你点一个赞。","有一次她发了一张教室的照片，黑板上写着「秋天的雨」。你盯着看了很久，最后什么也没说。"],"low":["你听说她过得很好。你替她高兴。真的。","只是有一年冬天，你在街上看见一个穿米色羽绒服的人，追了两步，才发现认错了。"]},"id":"sn_22","ending":"miss"},{"no":23,"title":"结局三 · 一辈子的朋友","week":60,"bg":"izakaya_night","cast":["sunian"],"steps":[{"t":"cast","list":["sunian"],"focus":"sunian"},{"t":"n","text":"你们做了一辈子的朋友。"},{"t":"n","text":"她结婚的时候，你是伴郎 / 伴娘。"},{"t":"n","text":"那天你起得很早，去她家帮忙贴喜字。她妈妈给你煮了一碗面，卧了两个鸡蛋。"},{"t":"n","text":"她坐在房间里化妆，从镜子里看见你，说：「你今天别哭。」"},{"t":"n","text":"你说你不哭。"},{"t":"n","text":"仪式上，她丈夫念誓词，念到一半忘了词。你在旁边小声提了一句，全场都笑了。"},{"t":"n","text":"她带毕业班那年，你是第一个去校门口等她的人。"},{"t":"n","text":"那阵子她天天改卷子到深夜。她丈夫在楼下等，把车里的暖气开得很足。"},{"t":"n","text":"你带了粥，带了充电宝，还带了一包她爱吃的奶片。"},{"t":"n","text":"毕业那天，她站在台上念名单。念到最后一个名字，声音有点抖。"},{"t":"n","text":"她班上的学生都认识你，叫你「那个总来接苏老师的朋友」。"},{"t":"n","text":"一届一届，叫了十几年。"},{"t":"n","text":"有一年你失恋，半夜给她打电话。"},{"t":"n","text":"她二话不说，开车过来，带了一袋橘子和两罐汽水。"},{"t":"n","text":"你们坐在楼下的花坛边。花坛里的月季早就谢了，只剩几根枝条。"},{"t":"n","text":"你把事情说了一遍。她没有劝，也没有骂那个人。"},{"t":"n","text":"她只是把橘子剥好，一瓣一瓣递给你。"},{"t":"n","text":"你说你不饿。她说：「剥都剥了。」"},{"t":"n","text":"你们喝到天亮。小区里的路灯灭了，扫地的人推着车过来。"},{"t":"n","text":"她说：「你说，咱们这样，算不算一辈子。」"},{"t":"n","text":"你说：「算。」"},{"t":"n","text":"她说：「那挺好的。」"},{"t":"n","text":"后来她当了教导主任。更忙了，头发剪得更短。"},{"t":"n","text":"她丈夫在学校教物理，两个人在同一栋楼上班，中午一起在食堂吃饭。"},{"t":"n","text":"她带过的学生回来看她，写贺卡，写「苏老师每天都在改作业，改到很晚」。"},{"t":"n","text":"你每年春节去她家吃饭。她丈夫给你倒茶，她班上的学生在门口贴春联。"},{"t":"n","text":"有一年，一个学生问你：「你是苏老师最好的朋友吧？那你怎么不住这儿。」"},{"t":"n","text":"你说，因为你有自己的家。"},{"t":"n","text":"学生「哦」了一声，又问：「那你以后老了怎么办。」"},{"t":"n","text":"她在一旁笑，说：「他/她有我们。」"},{"t":"choice","prompt":"","opts":[{"label":"A","text":"每年春节去她家吃饭","hint":"把她的家当半个家","eff":{"happy":3.0,"familyRel":2.0},"reply":[{"t":"n","text":"从那以后，你每年春节都去她家。她丈夫在厨房炒菜，你在客厅陪她爸爸下棋。"},{"t":"n","text":"她妈妈给你包红包，说：「家里没你，不像过年。」"},{"t":"n","text":"她看见了，说：「妈，你干嘛。」"},{"t":"n","text":"你说，总得有点表示。"},{"t":"n","text":"她看了你一会儿，把红包塞回你口袋：「拿着。你不拿，我妈不让我进厨房。」"}]},{"label":"B","text":"每年生日寄一张明信片","hint":"不常见面，也记着","eff":{"happy":2.0},"reply":[{"t":"n","text":"你每年她生日，都寄一张明信片。从不同的城市，不同的邮局。"},{"t":"n","text":"明信片上只写一句：「生日快乐。按时吃饭。」"},{"t":"n","text":"她收在一个铁盒里，放在书架上。"},{"t":"n","text":"有一年你忘了。她打电话来，说：「今年的呢。」"},{"t":"n","text":"你说补。她说：「不用补。你人来了就行。」"}]},{"label":"C","text":"不打扰，但随叫随到","hint":"把距离留好","eff":{"happy":1.0,"stress":-1.0},"reply":[{"t":"n","text":"你很少主动联系她。她也很少打扰你。"},{"t":"n","text":"但她半夜打电话，你一定接。"},{"t":"n","text":"有一次她打来，说自己发烧，她丈夫出差。你开车过去，送她去医院。"},{"t":"n","text":"挂号、缴费、拿药。你跑上跑下，她在输液室里，烧得迷迷糊糊。"},{"t":"n","text":"天亮的时候，她退烧了。她抬头看你，说：「谢谢你。」"},{"t":"n","text":"你说，客气什么。"}]}]}],"quality":{"high":["你们各自有家，各自有日子。但她家饭桌上，永远有一副给你留的碗筷。","你后来也遇到过别人，也好好谈过。成不成，都不影响你在她家有一个位置。"],"mid":["你们不常联系。有时候半年才通一次电话，说不了几句就挂了。","但你知道，只要拨过去，她一定接。她也知道，你会。"],"low":["你后来去了很远的城市，一年回来一次。她带的毕业班，一届一届地走。","有一年你回来，她愣了一下，还是叫出了你的名字。"]},"id":"sn_23","ending":"friend"}]}],"events":[{"id":"sn1","title":"她的生日","triggerWeek":0,"bg":"bedroom_night","intro":["她的生日在霜降前后。她从不主动提。"],"opts":[{"label":"A","text":"提前准备","hint":"早点记在日历上","eff":{"aff":4.0,"fin":-2.0},"reply":[{"t":"n","text":"你提前寄了一条围巾。她收到后拍了一张照，说「颜色太艳了」。第二天，她围着它去上课。"}]},{"label":"B","text":"当天想起来","hint":"当天发一句也好","eff":{"aff":2.0},"reply":[{"t":"n","text":"你晚上发了一句「生日快乐」。她回：「你还记得。」那头有学生在喊「苏老师」。"}]},{"label":"C","text":"忘了","hint":"日子过得太快了","eff":{"aff":-5.0,"happy":-3.0},"reply":[{"t":"n","text":"第二天你看见她发的朋友圈：一个很小的蛋糕，上面插着一根蜡烛。你点了一个赞。她没有回。"}]}]},{"id":"sn2","title":"下雨的伞","triggerWeek":0,"bg":"campus_night","intro":["你们从面馆出来，雨下大了。她只带了一把伞。"],"opts":[{"label":"A","text":"把伞给她","hint":"她明天还有课","eff":{"aff":3.0,"str":-1.0},"reply":[{"t":"n","text":"你把伞塞给她，自己跑进雨里。第二天，她给你带了一杯姜茶，放在桌上，什么也没说。"}]},{"label":"B","text":"一起淋雨","hint":"反正都湿了","eff":{"aff":4.0,"happy":2.0,"stress":1.0},"reply":[{"t":"n","text":"你们把书包顶在头上，跑过两条街。她在雨里笑得很大声，鞋里灌满了水。"}]},{"label":"C","text":"打车送她","hint":"别让她湿着回去","eff":{"fin":-2.0,"aff":2.0},"reply":[{"t":"n","text":"车里很闷。她坐在后排，看着窗外的雨。下车时，她说：「今天谢谢你。」"}]}]},{"id":"sn3","title":"旧照片","triggerWeek":30,"bg":"bedroom_night","intro":["你整理旧物，翻到一张小学毕业照。"],"opts":[{"label":"A","text":"发给她","hint":"让她也看看","eff":{"aff":3.0,"happy":2.0},"reply":[{"t":"n","text":"她回：「你那时候好矮。」过了一会儿，她发来一张她自己的，扎着两个辫子，站在第一排。"}]},{"label":"B","text":"自己留着","hint":"先收起来","eff":{"happy":1.0},"reply":[{"t":"n","text":"你把照片夹进一本书里。很多年后，你再翻到，边角已经黄了。"}]},{"label":"C","text":"删掉","hint":"过去就算了","eff":{"happy":-1.0},"reply":[{"t":"n","text":"你删了。过了一会儿，你去回收站找，已经清空了。"}]}]},{"id":"sn4","title":"厨房的灯","triggerWeek":55,"bg":"bedroom_night","intro":["她来你的出租屋，在你的厨房里做饭。"],"opts":[{"label":"A","text":"进去帮忙","hint":"别让她一个人忙","eff":{"aff":4.0,"familyRel":2.0},"reply":[{"t":"n","text":"你帮她择菜。她嫌你择得慢，把菜夺过去，又重新塞回你手里：「慢慢来。」"}]},{"label":"B","text":"在客厅等","hint":"让她自己来","eff":{"aff":1.0},"reply":[{"t":"n","text":"你坐在沙发上，听见她在厨房里哼歌。调子跑了，她自己也笑。"}]},{"label":"C","text":"接个工作电话","hint":"先把事情说完","eff":{"aff":-2.0,"stress":2.0},"reply":[{"t":"n","text":"你走到阳台。回来时，菜已经上桌，她一个人先吃了。她给你留了菜，用盘子扣着。"}]}]},{"id":"sn5","title":"同学婚礼","triggerWeek":45,"bg":"izakaya_night","intro":["高中同学结婚。你们都收到了请柬。"],"opts":[{"label":"A","text":"一起去","hint":"坐一桌","eff":{"aff":4.0,"happy":3.0},"reply":[{"t":"n","text":"有人问你们什么时候。她替你挡了：「他/她忙。先吃你的喜糖。」你在桌下碰了碰她的杯子。"}]},{"label":"B","text":"各自去","hint":"各走各的","eff":{},"reply":[{"t":"n","text":"你们在酒店门口碰见。她穿了一件米色的外套。你点了点头，她也点了点头。"}]},{"label":"C","text":"不去","hint":"那天有事","eff":{"aff":-2.0},"reply":[{"t":"n","text":"她一个人去了。回来发了一张合照，你在照片里找她，找了很久。"}]}]}]};
